import { Header } from "@/components/Header";
import { SosButton } from "@/components/SosButton";
import { QuickActions } from "@/components/ActionButtons";
import { MioSan } from "@/components/MioSan";
import { BottomNav } from "@/components/Navigation";
import { useSettings, useLogs, useEvents, useActiveSleepSession, useSleepSessions } from "@/hooks/use-app-data";
import { useState, useEffect, useMemo } from "react";
import { differenceInDays, differenceInMonths, differenceInMinutes, parseISO, addYears, format, isAfter, isSameDay, startOfDay } from "date-fns";
import { ja } from "date-fns/locale";
import { motion, AnimatePresence } from "framer-motion";
import { Trophy, Share2, Download, X, Gem, Moon, Heart, Siren, Gamepad2, Sprout, TreePine, Apple, Leaf, Zap, ChevronRight, Clock, AlertCircle, Milk, Baby, Sun } from "lucide-react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import html2canvas from "html2canvas";
import { useRef } from "react";

export default function Home() {
  const [familyId, setFamilyId] = useState(localStorage.getItem("familyId") || "default");
  const { data: settings, isLoading: isSettingsLoading } = useSettings(familyId);
  const [, navigate] = useLocation();
  const { data: logs, isLoading: isLogsLoading } = useLogs(familyId);
  const { data: events = [] } = useEvents(familyId);
  const { data: activeSession } = useActiveSleepSession(familyId);
  const { data: sleepSessions = [] } = useSleepSessions(familyId);
  const [showCertificate, setShowCertificate] = useState(false);
  const certificateRef = useRef<HTMLDivElement>(null);

  const totalPoints = logs?.reduce((sum: number, log: any) => sum + (log.points || 0), 0) || 0;
  const thanksCount = logs?.filter((log: any) => log.type === 'thanks').length || 0;
  const midnightCount = logs?.filter((log: any) => {
    const date = new Date(log.createdAt);
    const hour = date.getHours();
    return hour >= 0 && hour < 5;
  }).length || 0;
  const rescueCount = logs?.filter((log: any) => log.message === "レスキュー成功！").length || 0;
  const playCount = logs?.filter((log: any) => log.type === 'play').length || 0;

  const birthday = settings?.babyBirthday ? parseISO(settings.babyBirthday) : new Date();
  const firstBirthday = addYears(birthday, 1);
  const daysOld = Math.max(0, differenceInDays(new Date(), birthday));
  const daysUntilBirthday = Math.max(0, differenceInDays(firstBirthday, new Date()));

  const teamPower = Math.round((totalPoints + thanksCount * 5) / Math.max(1, daysOld));

  const today = startOfDay(new Date());
  const upcomingEvents = events
    .filter((e: any) => !e.completed && (isAfter(parseISO(e.date), today) || isSameDay(parseISO(e.date), today)))
    .sort((a: any, b: any) => parseISO(a.date).getTime() - parseISO(b.date).getTime())
    .slice(0, 2);

  useEffect(() => {
    if (!isSettingsLoading && settings && settings.babyName === "赤ちゃんのなまえ") {
      navigate("/settings");
    }
  }, [isSettingsLoading, settings, navigate]);

  useEffect(() => {
    if (daysOld >= 365 && !localStorage.getItem("certificate_shown")) {
      setShowCertificate(true);
    }
  }, [daysOld]);

  const closeCertificate = () => {
    setShowCertificate(false);
    localStorage.setItem("certificate_shown", "true");
  };

  const handleDownload = async () => {
    if (!certificateRef.current) return;
    try {
      const canvas = await html2canvas(certificateRef.current, {
        scale: 2,
        backgroundColor: "#ffffff",
        logging: false,
        useCORS: true
      });
      const image = canvas.toDataURL("image/png");
      const link = document.createElement("a");
      link.href = image;
      link.download = `strongest_team_certificate_${format(new Date(), 'yyyyMMdd')}.png`;
      link.click();
    } catch (err) {
      console.error("Failed to download certificate:", err);
    }
  };

  const handleShare = async () => {
    const shareText = `わが家が『最強チーム』に認定されました！🔥\n累計ポイント: ${totalPoints}pt\n深夜の奮闘: ${midnightCount}回\n#ペア育 #最強チーム認定証`;

    if (navigator.share) {
      try {
        await navigator.share({
          title: "最強チーム認定証",
          text: shareText,
          url: window.location.origin,
        });
      } catch (err) {
        if ((err as Error).name !== 'AbortError') {
          console.error("Error sharing:", err);
        }
      }
    } else {
      alert("このブラウザはシェアに対応していません。画像を保存して共有してくださいね。(みおさんより)");
    }
  };

  const months = settings?.babyBirthday ? differenceInMonths(new Date(), parseISO(settings.babyBirthday)) : 0;

  const isSleeping = activeSession?.id && !activeSession?.endedAt;

  const [sleepTimerMin, setSleepTimerMin] = useState(0);
  useEffect(() => {
    if (!isSleeping) return;
    const update = () => {
      const mins = differenceInMinutes(new Date(), new Date(activeSession.startedAt));
      setSleepTimerMin(Math.max(0, mins));
    };
    update();
    const interval = setInterval(update, 10000);
    return () => clearInterval(interval);
  }, [isSleeping, activeSession]);

  const lastCompletedSession = useMemo(() => {
    if (!sleepSessions || sleepSessions.length === 0) return null;
    const completed = sleepSessions.filter((s: any) => s.endedAt);
    if (completed.length === 0) return null;
    return completed[0];
  }, [sleepSessions]);

  const [wakeMinutes, setWakeMinutes] = useState(0);
  useEffect(() => {
    if (!lastCompletedSession || isSleeping) return;
    const update = () => {
      const mins = differenceInMinutes(new Date(), new Date(lastCompletedSession.endedAt));
      setWakeMinutes(Math.max(0, mins));
    };
    update();
    const interval = setInterval(update, 30000);
    return () => clearInterval(interval);
  }, [lastCompletedSession, isSleeping]);

  const wakeWindowAlert = useMemo(() => {
    if (!lastCompletedSession || isSleeping || wakeMinutes < 0) return null;
    const isUnder3m = months < 4;
    const warnMin = isUnder3m ? 60 : 120;
    const maxMin = isUnder3m ? 90 : 150;
    if (wakeMinutes < warnMin) return null;
    const isOverMax = wakeMinutes >= maxMin;
    if (isUnder3m) {
      return {
        level: isOverMax ? "urgent" : "warning",
        character: "みおさん",
        message: isOverMax
          ? "お疲れのご様子かもしれませんね。眠りのサインをそっと見守ってあげてくださいませ"
          : "そろそろお眠の時間かもしれません。あくびやお目をこする仕草はございませんか？",
      };
    }
    return {
      level: isOverMax ? "urgent" : "warning",
      character: "タカ先生",
      message: isOverMax
        ? "そろそろねんねのお時間っす！ゆっくり寝室へ移動してあげてくださいっす！"
        : "次のねんねの準備を始めてもいい頃かもしれないっす！お部屋を整えてあげるっすよ！",
    };
  }, [wakeMinutes, months, lastCompletedSession, isSleeping]);

  const todayMilkLogs = useMemo(() => {
    if (!logs) return [];
    const todayStart = startOfDay(new Date());
    return logs.filter((l: any) => l.type === "milk" && new Date(l.createdAt) >= todayStart);
  }, [logs]);

  const todayMilkCount = todayMilkLogs.length;
  const todayMilkMl = useMemo(() => {
    return todayMilkLogs.reduce((sum: number, l: any) => {
      return sum + (l.formulaMl || 0) + (l.expressedMl || 0);
    }, 0);
  }, [todayMilkLogs]);

  const todayDiaperCount = useMemo(() => {
    if (!logs) return 0;
    const todayStart = startOfDay(new Date());
    return logs.filter((l: any) => l.type === "diaper" && new Date(l.createdAt) >= todayStart).length;
  }, [logs]);

  const GrowthIcon = daysOld < 100 ? Sprout : daysOld < 200 ? Leaf : daysOld < 300 ? TreePine : Apple;

  const stats = [
    { label: "累計ポイント", value: `${totalPoints} pt`, Icon: Gem, color: "text-blue-400" },
    { label: "深夜の奮闘", value: `${midnightCount} 回`, Icon: Moon, color: "text-indigo-400" },
    { label: "ありがとう", value: `${thanksCount} 回`, Icon: Heart, color: "text-pink-400" },
    { label: "レスキュー成功", value: `${rescueCount} 回`, Icon: Siren, color: "text-red-400" },
    { label: "遊びの思い出", value: `${playCount} 回`, Icon: Gamepad2, color: "text-green-400" },
  ];

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50/50 via-white to-green-50/50 pb-24 font-sans">
      <div className="max-w-md mx-auto min-h-screen flex flex-col relative overflow-hidden">
        <Header 
          babyName={isSettingsLoading ? "読み込み中..." : settings?.babyName}
          caregiver={isSettingsLoading ? "..." : settings?.currentCaregiver}
        />

        <div className="px-8 pt-4 space-y-4">
          {/* カウントダウン表示 */}
          <div className="bg-white/60 backdrop-blur-sm rounded-3xl p-4 border border-white shadow-sm overflow-hidden relative">
            <div className="flex items-center justify-between relative z-10">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase">1歳の誕生日まで</p>
                <p className="text-lg font-black text-gray-700">あと <span className="text-2xl text-purple-500">{daysUntilBirthday}</span> 日</p>
              </div>
              <div className="w-10 h-10 rounded-full bg-green-50 flex items-center justify-center">
                <GrowthIcon className="w-6 h-6 text-green-500" />
              </div>
            </div>
            {/* 成長ゲージ */}
            <div className="mt-2 h-1.5 bg-gray-100 rounded-full overflow-hidden">
              <motion.div 
                initial={{ width: 0 }}
                animate={{ width: `${(daysOld / 365) * 100}%` }}
                className="h-full bg-gradient-to-r from-green-400 to-emerald-500"
              />
            </div>
          </div>

          <div className="bg-white/80 backdrop-blur-md rounded-[2rem] p-4 flex items-center justify-between border-2 border-purple-100 shadow-sm">
            <div className="flex items-center gap-3">
              <Zap className="w-6 h-6 text-purple-500 animate-bounce" />
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Team Power</p>
                <p className="text-xl font-black text-purple-600 tracking-tighter">{teamPower}</p>
              </div>
            </div>
            <div className="h-8 w-px bg-purple-100" />
            <div className="text-right">
              <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Total Points</p>
              <p className="text-xl font-black text-purple-600 tracking-tighter">{totalPoints} pt</p>
            </div>
          </div>

          <div className="bg-white/60 backdrop-blur-sm rounded-3xl p-4 border border-white shadow-sm" data-testid="card-today-stats">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider mb-3">Today's Summary</p>
            <div className="grid grid-cols-3 gap-3">
              <div className="text-center">
                <div className="w-8 h-8 mx-auto rounded-full bg-blue-50 flex items-center justify-center mb-1">
                  <Milk className="w-4 h-4 text-blue-500" />
                </div>
                <p className="text-lg font-black text-gray-700" data-testid="text-today-milk-count">{todayMilkCount}</p>
                <p className="text-[9px] text-gray-400 font-bold">授乳回数</p>
              </div>
              <div className="text-center">
                <div className="w-8 h-8 mx-auto rounded-full bg-blue-50 flex items-center justify-center mb-1">
                  <Milk className="w-4 h-4 text-blue-400" />
                </div>
                <p className="text-lg font-black text-gray-700" data-testid="text-today-milk-ml">{todayMilkMl}<span className="text-xs font-bold text-gray-400">ml</span></p>
                <p className="text-[9px] text-gray-400 font-bold">ミルク量</p>
              </div>
              <div className="text-center">
                <div className="w-8 h-8 mx-auto rounded-full bg-amber-50 flex items-center justify-center mb-1">
                  <Baby className="w-4 h-4 text-amber-500" />
                </div>
                <p className="text-lg font-black text-gray-700" data-testid="text-today-diaper-count">{todayDiaperCount}</p>
                <p className="text-[9px] text-gray-400 font-bold">おむつ回数</p>
              </div>
            </div>
          </div>
        </div>

        {isSleeping && (
          <div className="px-8 pt-2">
            <motion.div
              initial={{ opacity: 0, scale: 0.95 }}
              animate={{ opacity: 1, scale: 1 }}
              className="bg-gradient-to-r from-indigo-100 to-purple-100 rounded-3xl p-4 border-2 border-indigo-200 shadow-sm"
              data-testid="card-sleeping-now"
            >
              <div className="flex items-center gap-3">
                <div className="bg-indigo-200 p-2.5 rounded-2xl">
                  <Moon className="w-5 h-5 text-indigo-700" />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-[10px] font-bold text-indigo-400 uppercase tracking-wider">Now Sleeping</p>
                  <p className="text-lg font-black text-indigo-800" data-testid="text-sleeping-timer">
                    今、{Math.floor(sleepTimerMin / 60) > 0 ? `${Math.floor(sleepTimerMin / 60)}時間` : ""}{sleepTimerMin % 60}分ねんね中
                  </p>
                </div>
              </div>
              <div className="mt-2 pt-2 border-t border-indigo-200">
                <p className="text-xs font-bold text-indigo-600">
                  みお:「安らかなお顔ですね。この穏やかなひとときに、おふたりもどうぞごゆっくりお過ごしくださいませ。」
                </p>
              </div>
            </motion.div>
          </div>
        )}

        {!isSleeping && lastCompletedSession && (
          <div className="px-8 pt-2">
            <div className={`rounded-3xl p-4 border-2 shadow-sm transition-all ${
              wakeWindowAlert?.level === "urgent" 
                ? "bg-red-50/80 border-red-200" 
                : wakeWindowAlert?.level === "warning"
                ? "bg-amber-50/80 border-amber-200"
                : "bg-white/60 border-indigo-100"
            }`} data-testid="card-wake-window">
              <div className="flex items-center gap-3">
                <div className={`p-2.5 rounded-2xl ${
                  wakeWindowAlert?.level === "urgent" ? "bg-red-100" :
                  wakeWindowAlert?.level === "warning" ? "bg-amber-100" : "bg-indigo-50"
                }`}>
                  <Clock className={`w-5 h-5 ${
                    wakeWindowAlert?.level === "urgent" ? "text-red-600" :
                    wakeWindowAlert?.level === "warning" ? "text-amber-600" : "text-indigo-500"
                  }`} />
                </div>
                <div className="flex-1 min-w-0">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Wake Window</p>
                  <p className="text-lg font-black text-gray-700" data-testid="text-wake-time">
                    {Math.floor(wakeMinutes / 60)}時間{wakeMinutes % 60}分
                  </p>
                </div>
                {wakeWindowAlert && (
                  <AlertCircle className={`w-5 h-5 shrink-0 ${
                    wakeWindowAlert.level === "urgent" ? "text-red-500 animate-pulse" : "text-amber-500"
                  }`} />
                )}
              </div>
              {wakeWindowAlert && (
                <div className={`mt-2 pt-2 border-t ${
                  wakeWindowAlert.level === "urgent" ? "border-red-200" : "border-amber-200"
                }`}>
                  <p className={`text-xs font-bold ${
                    wakeWindowAlert.level === "urgent" ? "text-red-700" : "text-amber-700"
                  }`} data-testid="text-wake-advice">
                    {wakeWindowAlert.character}:「{wakeWindowAlert.message}」
                  </p>
                </div>
              )}
            </div>
          </div>
        )}

        {upcomingEvents.length > 0 && (
          <div className="px-8 pt-2">
            <Link href="/calendar" className="block" data-testid="link-upcoming-events">
              <div className="bg-white/70 backdrop-blur-sm rounded-2xl p-3 border border-purple-100 shadow-sm">
                <div className="flex items-center justify-between mb-2">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wider">Next Schedule</p>
                  <span className="text-[10px] text-purple-400 font-bold">{'>'}</span>
                </div>
                <div className="space-y-1.5">
                  {upcomingEvents.map((event: any) => (
                    <div key={event.id} className="flex items-center gap-2" data-testid={`upcoming-event-${event.id}`}>
                      <div className="w-1.5 h-1.5 rounded-full bg-purple-400 shrink-0" />
                      <span className="text-xs font-bold text-gray-600 truncate flex-1">{event.title}</span>
                      <span className="text-[10px] text-gray-400 shrink-0">
                        {format(parseISO(event.date), "M/d（E）", { locale: ja })}
                      </span>
                    </div>
                  ))}
                </div>
              </div>
            </Link>
          </div>
        )}

        <main className="flex-1 flex flex-col items-center w-full z-10">
          <SosButton />
          <section className="w-full mb-8">
            <div className="px-8 mb-4 flex items-center justify-between">
              <h3 className="font-bold text-gray-700 text-lg">クイックログ</h3>
            </div>
            <QuickActions />
          </section>

          <div className="px-8 mb-6 w-full">
            <Link href="/health" className="block" data-testid="link-health">
              <div className="bg-gradient-to-r from-teal-50 to-green-50 rounded-3xl p-4 border-2 border-teal-100 shadow-sm hover-elevate">
                <div className="flex items-center gap-3">
                  <div className="bg-teal-100 p-2.5 rounded-2xl">
                    <Heart className="w-5 h-5 text-teal-600" />
                  </div>
                  <div className="flex-1">
                    <p className="font-black text-sm text-teal-800">健康・成長記録</p>
                    <p className="text-[10px] text-teal-500 mt-0.5">体温・おむつ詳細・症状メモ・成長曲線</p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-teal-400" />
                </div>
              </div>
            </Link>
          </div>

          <div className="px-8 mb-6 w-full">
            <Link href="/skills" className="block" data-testid="link-skills">
              <div className="bg-gradient-to-r from-amber-50 to-purple-50 rounded-3xl p-4 border-2 border-amber-100 shadow-sm hover-elevate">
                <div className="flex items-center gap-3">
                  <div className="bg-amber-100 p-2.5 rounded-2xl">
                    <Trophy className="w-5 h-5 text-amber-600" />
                  </div>
                  <div className="flex-1">
                    <p className="font-black text-sm text-amber-800">スキル図鑑</p>
                    <p className="text-[10px] text-amber-500 mt-0.5">育児スキルを習得してランクアップ</p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-amber-400" />
                </div>
              </div>
            </Link>
          </div>

          <div className="px-8 mb-6 w-full">
            <Link href="/sleep-training" className="block" data-testid="link-sleep-training">
              <div className="bg-gradient-to-r from-indigo-50 to-purple-50 rounded-3xl p-4 border-2 border-indigo-100 shadow-sm hover-elevate">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-100 p-2.5 rounded-2xl">
                    <Moon className="w-5 h-5 text-indigo-600" />
                  </div>
                  <div className="flex-1">
                    <p className="font-black text-sm text-indigo-800">ネントレ支援</p>
                    <p className="text-[10px] text-indigo-500 mt-0.5">環境チェック・ルーティン・見守りタイマー</p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-indigo-400" />
                </div>
              </div>
            </Link>
          </div>

          <div className="px-8 mb-6 w-full">
            <Link href="/dashboard" className="block" data-testid="link-dashboard">
              <div className="bg-gradient-to-r from-purple-50 to-rose-50 rounded-3xl p-4 border-2 border-purple-100 shadow-sm hover-elevate">
                <div className="flex items-center gap-3">
                  <div className="bg-purple-100 p-2.5 rounded-2xl">
                    <Gem className="w-5 h-5 text-purple-600" />
                  </div>
                  <div className="flex-1">
                    <p className="font-black text-sm text-purple-800">貢献度ダッシュボード</p>
                    <p className="text-[10px] text-purple-500 mt-0.5">ふたりの育児をグラフで可視化</p>
                  </div>
                  <ChevronRight className="w-4 h-4 text-purple-400" />
                </div>
              </div>
            </Link>
          </div>

          <MioSan />
        </main>
      </div>

      {/* 最強チーム認定証 */}
      <AnimatePresence>
        {showCertificate && (
          <motion.div 
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-black/60 backdrop-blur-md flex items-center justify-center p-6"
            onClick={closeCertificate}
            data-testid="overlay-certificate"
          >
            <motion.div 
              initial={{ scale: 0.9, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              className="bg-white w-full max-w-sm rounded-[3rem] overflow-hidden shadow-2xl relative border-8 border-purple-100"
              onClick={(e) => e.stopPropagation()}
            >
              <button 
                onClick={closeCertificate}
                className="absolute top-4 right-4 p-2 bg-gray-100 rounded-full text-gray-500 hover:bg-gray-200 z-50"
              >
                <X className="w-4 h-4" />
              </button>

              <div ref={certificateRef} className="p-8 text-center space-y-6 bg-white">
                <div className="flex justify-center">
                  <div className="bg-purple-100 p-4 rounded-full">
                    <Trophy className="w-12 h-12 text-purple-500" />
                  </div>
                </div>

                <div className="space-y-1">
                  <h2 className="text-3xl font-black text-purple-600">最強チーム認定証</h2>
                  <p className="text-sm font-bold text-gray-400">祝・1歳の誕生日</p>
                </div>

                <div className="bg-purple-50 rounded-2xl p-4 border border-purple-100">
                  <p className="text-sm font-bold text-gray-600" data-testid="text-certificate-family">
                    パパ ＆ ママ ＆ {settings?.babyName || "赤ちゃん"}殿
                  </p>
                  <p className="text-[10px] text-gray-400 mt-2 leading-relaxed">
                    あなたたちは、この1年間、最高の連携と愛情をもって
                    育児という大冒険を共に歩んできました。
                    ここにその功績を称え、最強のチームであることを証明します。
                  </p>
                </div>

                <div className="grid grid-cols-2 gap-2">
                  {stats.map(s => (
