import { motion } from "framer-motion";
import { useState, useEffect } from "react";
import { useSettings } from "@/hooks/use-app-data";
import { differenceInMonths, parseISO } from "date-fns";
import { Heart, Zap } from "lucide-react";

export function MioSan() {
  const familyId = localStorage.getItem("familyId") || "default";
  const { data: settings } = useSettings(familyId);
  const [message, setMessage] = useState("");

  const months = settings?.babyBirthday ? differenceInMonths(new Date(), parseISO(settings.babyBirthday)) : 0;
  const isTakaSensei = months >= 4;
  const babyName = settings?.babyName && settings.babyName !== "赤ちゃんのなまえ" ? settings.babyName : "";

  const character = isTakaSensei ? {
    name: "保育士 タカ先生",
    IconComponent: Zap,
    iconColor: "text-blue-500",
    personality: "熱血系",
    defaultMsg: babyName
      ? `${babyName}、今日も元気いっぱいっすね！パパもママも素晴らしいチームワークっすよ！いつも本当にお疲れ様っす！`
      : "今日もナイスチームワークっす！おふたりの頑張り、しっかり見守っていますよ！",
    avatarBg: "bg-blue-100"
  } : {
    name: "助産師 みおさん",
    IconComponent: Heart,
    iconColor: "text-purple-500",
    personality: "癒やし系",
    defaultMsg: babyName
      ? `${babyName}のお世話、本日もお疲れ様でございます。どうぞご無理なさらず、おふたりの時間も大切になさってくださいね`
      : "本日もお疲れ様でございます。おふたりの頑張りを、心より応援しております",
    avatarBg: "bg-purple-100"
  };

  useEffect(() => {
    if (!message) setMessage(character.defaultMsg);
  }, [character.defaultMsg]);

  useEffect(() => {
    const handlePoints = (e: any) => {
      const { points: pts, type } = e.detail;
      let feedback = "";

      if (isTakaSensei) {
        if (type === 'play') {
          feedback = babyName
            ? `素敵な遊びの時間っすね！${babyName}もとっても楽しそうっす！${pts}ptゲットっす！`
            : `素敵な遊びの時間っすね！お子様もとっても楽しそうっす！${pts}ptゲットっす！`;
        } else if (type === 'thanks') {
          feedback = "おふたりの連携、本当に素晴らしいっす！感謝の気持ちが最高のチーム力っすよ！";
        } else {
          feedback = `さすがの連携っす！${pts}ptゲット！おふたりのチームワークに感動っす！`;
        }
      } else {
        feedback = babyName
          ? `${babyName}のために、素敵なお世話をありがとうございます。${pts}pt、おふたりの宝物ですね`
          : `丁寧なお世話をありがとうございます。${pts}pt、おふたりの絆の証ですね`;
      }

      setMessage(feedback);
      setTimeout(() => setMessage(character.defaultMsg), 5000);
    };
    window.addEventListener('new-log-pts', handlePoints);
    return () => window.removeEventListener('new-log-pts', handlePoints);
  }, [isTakaSensei, character.defaultMsg, babyName]);

  return (
    <div className="w-full max-w-md mx-auto mt-auto px-6 pb-8">
      <div className="relative">
        <motion.div 
          key={message}
          initial={{ opacity: 0, y: 10, scale: 0.95 }}
          animate={{ opacity: 1, y: 0, scale: 1 }}
          className="bg-white rounded-[24px] rounded-bl-none p-5 shadow-soft border border-purple-50 mb-4 relative z-10"
        >
          <p className="text-sm text-gray-600 leading-relaxed font-medium" data-testid="text-ai-message">
            {message}
          </p>
        </motion.div>

        <div className="flex items-end gap-3">
          <div className="relative">
            <div className={`w-14 h-14 rounded-full ${character.avatarBg} shadow-inner flex items-center justify-center overflow-hidden border-2 border-white ring-2 ring-purple-100`}>
              <character.IconComponent className={`w-6 h-6 ${character.iconColor}`} />
            </div>
            <div className="absolute -bottom-1 -right-1 w-5 h-5 bg-green-400 rounded-full border-2 border-white" />
          </div>
          <div className="flex flex-col pb-1">
            <span className="text-sm font-bold text-gray-800" data-testid="text-ai-name">{character.name}</span>
            <span className="text-xs text-purple-400 font-medium">{character.personality}AIサポーター</span>
          </div>
        </div>
      </div>
    </div>
  );
}

