import { useState } from "react";
import { Header } from "@/components/Header";
import { BottomNav } from "@/components/Navigation";
import { useSettings, useEvents, useCreateEvent, useCompleteEvent, useDeleteEvent } from "@/hooks/use-app-data";
import { format, startOfMonth, endOfMonth, eachDayOfInterval, isSameDay, isSameMonth, addMonths, subMonths, isToday, isBefore, parseISO } from "date-fns";
import { ja } from "date-fns/locale";
import { motion, AnimatePresence } from "framer-motion";
import { ChevronLeft, ChevronRight, Plus, Check, Trash2, X, Clock, User } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

const WEEKDAYS = ["日", "月", "火", "水", "木", "金", "土"];

export default function Calendar() {
  const familyId = localStorage.getItem("familyId") || "default";
  const { data: settings } = useSettings(familyId);
  const { data: events = [], isLoading } = useEvents(familyId);
  const createEvent = useCreateEvent();
  const completeEvent = useCompleteEvent();
  const deleteEvent = useDeleteEvent();

  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | null>(null);
  const [showAddDialog, setShowAddDialog] = useState(false);
  const [newTitle, setNewTitle] = useState("");
  const [newTime, setNewTime] = useState("");
  const [newAssignee, setNewAssignee] = useState("未定");
  const [newMemo, setNewMemo] = useState("");

  const monthStart = startOfMonth(currentMonth);
  const monthEnd = endOfMonth(currentMonth);
  const days = eachDayOfInterval({ start: monthStart, end: monthEnd });

  const startDayOfWeek = monthStart.getDay();
  const paddingDays = Array.from({ length: startDayOfWeek }, (_, i) => i);

  const getEventsForDate = (date: Date) => {
    return events.filter((e: any) => {
      const eventDate = parseISO(e.date);
      return isSameDay(eventDate, date);
    });
  };

  const selectedDateEvents = selectedDate ? getEventsForDate(selectedDate) : [];

  const handleAddEvent = () => {
    if (!newTitle.trim() || !selectedDate) return;
    createEvent.mutate({
      familyId,
      title: newTitle.trim(),
      date: format(selectedDate, "yyyy-MM-dd"),
      time: newTime || null,
      assignee: newAssignee,
      memo: newMemo || null,
    });
    setNewTitle("");
    setNewTime("");
    setNewAssignee("未定");
    setNewMemo("");
    setShowAddDialog(false);
  };

  const handleComplete = (eventId: number) => {
    const userId = localStorage.getItem("userType") || "papa";
    completeEvent.mutate({ id: eventId, completedBy: userId });
  };

  const handleDelete = (eventId: number) => {
    deleteEvent.mutate(eventId);
  };

  const assigneeColor = (assignee: string) => {
    if (assignee === "パパ") return "bg-blue-100 text-blue-700";
    if (assignee === "ママ") return "bg-pink-100 text-pink-700";
    return "bg-gray-100 text-gray-500";
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-purple-50/50 via-white to-green-50/50 pb-24 font-sans">
      <div className="max-w-md mx-auto min-h-screen flex flex-col">
        <Header
          babyName={settings?.babyName}
          caregiver={settings?.currentCaregiver}
        />

        <div className="px-6 pt-4 space-y-4">
          {/* Month Navigation */}
          <div className="flex items-center justify-between">
            <Button
              size="icon"
              variant="ghost"
              onClick={() => setCurrentMonth(subMonths(currentMonth, 1))}
              data-testid="button-prev-month"
            >
              <ChevronLeft className="w-5 h-5" />
            </Button>
            <h2 className="text-lg font-black text-gray-700" data-testid="text-current-month">
              {format(currentMonth, "yyyy年 M月", { locale: ja })}
            </h2>
            <Button
              size="icon"
              variant="ghost"
              onClick={() => setCurrentMonth(addMonths(currentMonth, 1))}
              data-testid="button-next-month"
            >
              <ChevronRight className="w-5 h-5" />
            </Button>
          </div>

          {/* Calendar Grid */}
          <div className="bg-white/80 backdrop-blur-md rounded-3xl p-4 border border-white shadow-sm">
            <div className="grid grid-cols-7 gap-1 mb-2">
              {WEEKDAYS.map((day, i) => (
                <div
                  key={day}
                  className={cn(
                    "text-center text-[10px] font-bold py-1",
                    i === 0 ? "text-red-400" : i === 6 ? "text-blue-400" : "text-gray-400"
                  )}
                >
                  {day}
                </div>
              ))}
            </div>

            <div className="grid grid-cols-7 gap-1">
              {paddingDays.map((_, i) => (
                <div key={`pad-${i}`} className="aspect-square" />
              ))}
              {days.map((day) => {
                const dayEvents = getEventsForDate(day);
                const hasEvents = dayEvents.length > 0;
                const allCompleted = hasEvents && dayEvents.every((e: any) => e.completed);
                const hasIncomplete = dayEvents.some((e: any) => !e.completed);
                const isSelected = selectedDate && isSameDay(day, selectedDate);
                const isPast = isBefore(day, new Date()) && !isToday(day);
                const dayOfWeek = day.getDay();

                return (
                  <motion.button
                    key={day.toISOString()}
                    whileTap={{ scale: 0.92 }}
                    onClick={() => setSelectedDate(day)}
                    data-testid={`button-day-${format(day, "yyyy-MM-dd")}`}
                    className={cn(
                      "aspect-square rounded-2xl flex flex-col items-center justify-center relative transition-all",
                      isSelected
                        ? "bg-purple-500 text-white shadow-lg shadow-purple-200"
                        : isToday(day)
                          ? "bg-purple-50 text-purple-600 ring-2 ring-purple-200"
                          : isPast
                            ? "text-gray-300"
                            : "text-gray-700",
                      dayOfWeek === 0 && !isSelected ? "text-red-400" : "",
                      dayOfWeek === 6 && !isSelected ? "text-blue-400" : ""
                    )}
                  >
                    <span className={cn("text-sm font-bold", isPast && !isSelected && "text-gray-300")}>
                      {format(day, "d")}
                    </span>
                    {hasEvents && (
                      <div className="flex gap-0.5 mt-0.5">
                        {allCompleted ? (
                          <div className="w-1.5 h-1.5 rounded-full bg-green-400" />
                        ) : hasIncomplete ? (
                          <div className={cn("w-1.5 h-1.5 rounded-full", isSelected ? "bg-white" : "bg-purple-400")} />
                        ) : null}
                      </div>
                    )}
                  </motion.button>
                );
              })}
            </div>
          </div>

          {/* Selected Date Events */}
          <AnimatePresence mode="wait">
            {selectedDate && (
              <motion.div
                key={selectedDate.toISOString()}
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -10 }}
                className="space-y-3"
              >
                <div className="flex items-center justify-between">
                  <h3 className="font-bold text-gray-700" data-testid="text-selected-date">
                    {format(selectedDate, "M月d日（E）", { locale: ja })}
                  </h3>
                  <Button
                    size="sm"
                    onClick={() => setShowAddDialog(true)}
                    className="rounded-2xl bg-purple-500 text-white font-bold shadow-sm"
                    data-testid="button-add-event"
                  >
                    <Plus className="w-4 h-4 mr-1" /> 予定を追加
                  </Button>
                </div>

                {selectedDateEvents.length === 0 ? (
                  <div className="bg-white/60 backdrop-blur-sm rounded-3xl p-6 text-center border border-white shadow-sm">
                    <p className="text-gray-400 text-sm">この日の予定はありません</p>
                  </div>
                ) : (
                  <div className="space-y-2">
                    {selectedDateEvents.map((event: any) => (
                      <motion.div
                        key={event.id}
                        layout
                        className={cn(
                          "bg-white/80 backdrop-blur-sm rounded-2xl p-4 border shadow-sm",
                          event.completed
                            ? "border-green-100 opacity-70"
                            : "border-purple-100"
                        )}
                        data-testid={`card-event-${event.id}`}
                      >
                        <div className="flex items-start justify-between gap-2">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 flex-wrap">
                              <p className={cn(
                                "font-bold text-sm",
                                event.completed ? "text-gray-400 line-through" : "text-gray-700"
                              )}>
                                {event.title}
                              </p>
                              <span className={cn("text-[10px] font-bold px-2 py-0.5 rounded-full", assigneeColor(event.assignee))}>
                                {event.assignee}
                              </span>
                            </div>
                            {event.time && (
                              <div className="flex items-center gap-1 mt-1">
                                <Clock className="w-3 h-3 text-gray-400" />
                                <span className="text-xs text-gray-400">{event.time}</span>
                              </div>
                            )}
                            {event.memo && (
                              <p className="text-xs text-gray-400 mt-1">{event.memo}</p>
                            )}
                            {event.completed && event.completedBy && (
                              <div className="flex items-center gap-1 mt-1">
                                <User className="w-3 h-3 text-green-500" />
                                <span className="text-[10px] text-green-600 font-bold">{event.completedBy === "papa" ? "パパ" : "ママ"}が完了 +10pt</span>
                              </div>
                            )}
                          </div>
                          <div className="flex items-center gap-1 shrink-0">
                            {!event.completed && (
                              <Button
                                size="icon"
                                variant="ghost"
                                onClick={() => handleComplete(event.id)}
                                className="text-green-500"
                                data-testid={`button-complete-${event.id}`}
                              >
                                <Check className="w-4 h-4" />
                              </Button>
                            )}
                            <Button
                              size="icon"
                              variant="ghost"
                              onClick={() => handleDelete(event.id)}
                              className="text-gray-300"
                              data-testid={`button-delete-${event.id}`}
                            >
                              <Trash2 className="w-4 h-4" />
                            </Button>
                          </div>
                        </div>
                      </motion.div>
                    ))}
                  </div>
                )}
              </motion.div>
            )}
          </AnimatePresence>
        </div>
      </div>

      {/* Add Event Dialog */}
      <AnimatePresence>
        {showAddDialog && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] bg-black/40 backdrop-blur-sm flex items-end justify-center"
            onClick={(e) => { if (e.target === e.currentTarget) setShowAddDialog(false); }}
          >
            <motion.div
              initial={{ y: "100%" }}
              animate={{ y: 0 }}
              exit={{ y: "100%" }}
              transition={{ type: "spring", damping: 25, stiffness: 300 }}
              className="w-full max-w-md bg-white rounded-t-[2rem] p-6 space-y-4 shadow-2xl"
            >
              <div className="flex items-center justify-between">
                <h3 className="font-black text-gray-700 text-lg">予定を追加</h3>
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => setShowAddDialog(false)}
                  data-testid="button-close-dialog"
                >
                  <X className="w-5 h-5" />
                </Button>
              </div>

              <div className="space-y-3">
                <div>
                  <label className="text-xs font-bold text-gray-400 block mb-1">タイトル</label>
                  <input
                    type="text"
                    value={newTitle}
                    onChange={(e) => setNewTitle(e.target.value)}
                    placeholder="例：予防接種、健診"
                    className="w-full px-4 py-3 rounded-2xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-300"
                    data-testid="input-event-title"
                  />
                </div>

                <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="text-xs font-bold text-gray-400 block mb-1">時間（任意）</label>
                    <input
                      type="time"
                      value={newTime}
                      onChange={(e) => setNewTime(e.target.value)}
                      className="w-full px-4 py-3 rounded-2xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-300"
                      data-testid="input-event-time"
                    />
                  </div>
                  <div>
                    <label className="text-xs font-bold text-gray-400 block mb-1">担当</label>
                    <select
                      value={newAssignee}
                      onChange={(e) => setNewAssignee(e.target.value)}
                      className="w-full px-4 py-3 rounded-2xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-300 bg-white"
                      data-testid="select-event-assignee"
                    >
                      <option value="未定">未定</option>
                      <option value="パパ">パパ</option>
                      <option value="ママ">ママ</option>
                    </select>
                  </div>
                </div>

                <div>
                  <label className="text-xs font-bold text-gray-400 block mb-1">メモ（任意）</label>
                  <input
                    type="text"
                    value={newMemo}
                    onChange={(e) => setNewMemo(e.target.value)}
                    placeholder="持ち物や注意点など"
                    className="w-full px-4 py-3 rounded-2xl border border-gray-200 text-sm focus:outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-300"
                    data-testid="input-event-memo"
                  />
                </div>

                <Button
                  onClick={handleAddEvent}
                  disabled={!newTitle.trim() || createEvent.isPending}
                  className="w-full rounded-2xl h-12 bg-purple-500 text-white font-black shadow-lg shadow-purple-100"
                  data-testid="button-submit-event"
                >
                  {createEvent.isPending ? "追加中..." : "この日に追加する"}
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  );
}

