import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { ArrowLeft, CheckCircle2, ChevronRight, Timer, AlertCircle, Info } from "lucide-react";
import { Link, useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { useSettings, useCreateLog } from "@/hooks/use-app-data";
import { differenceInMonths, parseISO } from "date-fns";

export default function Rescue() {
  const [, setLocation] = useLocation();
  const familyId = localStorage.getItem("familyId") || "default";
  const { data: settings } = useSettings(familyId);
  const { mutate: createLog } = useCreateLog();
  const [step, setStep] = useState(0);
  const [showTimer, setShowTimer] = useState(false);
  const [timeLeft, setTimeLeft] = useState(15 * 60);

  const months = settings?.babyBirthday ? differenceInMonths(new Date(), parseISO(settings.babyBirthday)) : 0;
  const isTakaSensei = months >= 4;

  const character = isTakaSensei ? {
    name: "保育士 タカ先生",
    icon: "👨‍🏫",
    personality: "熱血系",
    style: "bg-[#F5F0FF] text-[#805AAA] border-[#D4C4E8]",
    avatarBg: "bg-[#D4C4E8]",
    bubbleStyle: "bg-white border-[#D4C4E8] text-purple-900"
  } : {
    name: "助産師 みおさん",
    icon: "👩‍⚕️",
    personality: "癒やし系",
    style: "bg-[#F8F5FF] text-[#B19CD9] border-[#E8E0FF]",
    avatarBg: "bg-[#E8E0FF]",
    bubbleStyle: "bg-white border-[#E8E0FF] text-purple-900"
  };

  const mioSteps = [
    { title: "おむつ確認", desc: "まずは一番多い理由から確認してまいりましょう。おむつは濡れていませんでしょうか？" },
    { title: "お腹の確認", desc: "前回のお食事やミルクから少しお時間が空いていませんか？お腹が空いているのかもしれませんね。" },
    { title: "ゲップ・ガス", desc: "お腹に空気が溜まって苦しいのかもしれません。やさしく縦抱きにしてみてくださいませ。" },
    { title: "刺激のリセット", desc: "テレビを消して、お部屋を少し暗くして、静かな環境を整えてみましょう。" },
    { title: "睡眠スケジュール", desc: "最後にお目覚めになってから1.5時間以上経っていませんか？お疲れで眠れないのかもしれません。" },
    { title: "温度・環境", desc: "暑すぎたり寒すぎたりしていませんか？背中にそっと手を入れてご確認くださいませ。" },
    { title: "全身チェック", desc: "お洋服のタグがお肌に当たっていたり、小さな指に髪の毛が絡まったりしていませんか？" },
  ];

  const takaSteps = [
    { title: "環境チェンジ", desc: "お部屋の景色を変えてみるっす！窓の外を見せたり、ベランダでお外の空気を感じさせてあげるっすよ！" },
    { title: "おもちゃ・音", desc: `少し退屈しているのかもしれないっす！${settings?.specialTrick || "ビニール袋の音"}を聞かせてみるっす！` },
    { title: "ふれあい遊び", desc: "やさしく体を使って遊んでみるっす！そっとこちょこちょしたり、お歌を歌ってあげるっす！" },
    { title: "歯ぐずりの確認", desc: "よだれが増えていませんか？歯が生え始めてむずがゆいのかもしれないっす！" },
    { title: "悔しさへの共感", desc: "何かやりたいことがあるのかもしれないっす。そっと手を添えてお手伝いしてあげるっす！" },
    { title: "メンタルリープ", desc: "今は大きく成長している時期かもしれないっす！そばに寄り添うだけで十分っすよ！" },
    { title: "担当交代", desc: "パートナーにバトンタッチするのも素敵な作戦っす！おふたりの連携で乗り越えるっす！" },
  ];

  const steps = isTakaSensei ? takaSteps : mioSteps;

  useEffect(() => {
    let timer: NodeJS.Timeout;
    if (showTimer && timeLeft > 0) {
      timer = setInterval(() => setTimeLeft((t) => t - 1), 1000);
    }
    return () => clearInterval(timer);
  }, [showTimer, timeLeft]);

  const handleComplete = () => {
    createLog({ type: "sos", message: "レスキュー成功！" });
    setLocation("/");
  };

  const handleNext = () => {
    if (step < steps.length - 1) {
      setStep(step + 1);
    } else {
      setShowTimer(true);
      createLog({ type: "sos", message: "抱っこリレー開始！応援要請！" });
    }
  };

  const formatTime = (seconds: number) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className={`min-h-screen font-sans transition-colors duration-500 ${character.style}`}>
      <div className="max-w-md mx-auto px-6 py-8 h-screen flex flex-col">
        <div className="flex items-center gap-4 mb-8">
          <Link href="/">
            <Button variant="ghost" size="icon" className="rounded-full hover:bg-black/5">
              <ArrowLeft className="w-6 h-6" />
            </Button>
          </Link>
          <h1 className="text-xl font-black">泣き止みレスキュー</h1>
        </div>

        <div className="flex-1 flex flex-col justify-center gap-6">
          <AnimatePresence mode="wait">
            {!showTimer ? (
              <motion.div
                key={step}
                initial={{ opacity: 0, x: 20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -20 }}
                className="space-y-6"
              >
                <div className="flex items-center gap-4 mb-2">
                  <div className={`w-12 h-12 rounded-full ${character.avatarBg} flex items-center justify-center text-2xl border-2 border-white shadow-sm`}>
                    {character.icon}
                  </div>
                  <div>
                    <p className="text-xs font-bold opacity-70">{character.name}</p>
                    <p className="text-sm font-black">ステップ {step + 1} / {steps.length}</p>
                  </div>
                </div>

                <div className={`${character.bubbleStyle} rounded-[32px] rounded-tl-none p-8 shadow-soft border-2 transition-all duration-300`}>
                  <h2 className="text-2xl font-black mb-4">{steps[step].title}</h2>
                  <p className="text-lg opacity-90 leading-relaxed font-bold">{steps[step].desc}</p>
                </div>

                <div className="grid grid-cols-2 gap-4">
                  <Button onClick={handleComplete} variant="outline" className="h-16 rounded-2xl border-2 font-black border-green-500 text-green-600 hover:bg-green-50 active:scale-95 transition-transform">
                    <CheckCircle2 className="w-5 h-5 mr-2" /> 解決！
                  </Button>
                  <Button 
                    onClick={handleNext} 
                    className={`h-16 rounded-2xl font-black shadow-lg active:scale-95 transition-transform ${isTakaSensei ? "bg-primary hover:bg-primary/90" : "bg-secondary hover:bg-secondary/90"}`}
                  >
                    {step === steps.length - 1 ? "リレー要請" : "次へ"} <ChevronRight className="w-5 h-5 ml-1" />
                  </Button>
                </div>

                <div className="flex items-center gap-2 p-4 bg-yellow-50 rounded-2xl border border-yellow-100 mt-4">
                  <Info className="w-5 h-5 text-yellow-600 shrink-0" />
                  <p className="text-[10px] text-yellow-800 font-bold leading-tight">
                    全ての項目を確認しても泣き止まず、「熱がある」「ぐったりしている」「異常な泣き方」の場合は、すみやかに医療機関に相談してください。
                  </p>
                </div>
              </motion.div>
            ) : (
              <motion.div
                initial={{ scale: 0.9, opacity: 0 }}
                animate={{ scale: 1, opacity: 1 }}
                className="text-center space-y-8"
              >
                <div className="bg-red-50 p-8 rounded-[40px] border-4 border-red-200 shadow-xl">
                  <div className="flex justify-center mb-6">
                    <div className="bg-red-500 p-5 rounded-full animate-pulse shadow-lg shadow-red-200">
                      <Timer className="w-12 h-12 text-white" />
                    </div>
                  </div>
                  <h2 className="text-3xl font-black text-red-600 mb-2">抱っこリレー開始！</h2>
                  <p className="text-red-900 font-bold opacity-70 mb-6 leading-relaxed">
                    パートナーの画面に「応援要請」を表示しました。<br/>
                    あと少し、交代して乗り切りましょう！
                  </p>
                  <div className="text-6xl font-black text-red-600 font-mono tracking-tighter tabular-nums">
                    {formatTime(timeLeft)}
                  </div>
                </div>
                <Button onClick={() => setLocation("/")} variant="ghost" className="font-black text-gray-500 hover:bg-gray-100 h-12 rounded-xl">
                  ホームに戻る
                </Button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        <div className="flex items-center justify-center gap-2 py-6">
          {steps.map((_, i) => (
            <div key={i} className={`h-2 rounded-full transition-all duration-300 ${i === step ? "w-8 bg-current" : "w-2 bg-current/20"}`} />
          ))}
        </div>
      </div>
    </div>
  );
}

