const LEVEL_COLORS: Record<string, string> = {
  "初級": "bg-green-100 text-green-700",
  "中級": "bg-blue-100 text-blue-700",
  "上級": "bg-purple-100 text-purple-700",
  "達人": "bg-amber-100 text-amber-700",
};

const RANK_THRESHOLDS = [
  { name: "ルーキー", minXP: 0, icon: Star },
  { name: "レギュラー", minXP: 200, icon: Award },
  { name: "エース", minXP: 500, icon: Zap },
  { name: "ベテランコーチ", minXP: 1000, icon: Trophy },
  { name: "レジェンド", minXP: 2000, icon: Sparkles },
];

function getRank(xp: number) {
  let rank = RANK_THRESHOLDS[0];
  for (const t of RANK_THRESHOLDS) {
    if (xp >= t.minXP) rank = t;
  }
  return rank;
}

function getNextRank(xp: number) {
  for (const t of RANK_THRESHOLDS) {
    if (xp < t.minXP) return t;
  }
  return null;
}

export default function SkillTree() {
  const familyId = localStorage.getItem("familyId") || "default";
  const userId = localStorage.getItem("userType") || "papa";
  const { data: completions = [] } = useSkillCompletions(familyId);
  const completeSkill = useCompleteSkill();
  const uncompleteSkill = useUncompleteSkill();
  const [expandedCategory, setExpandedCategory] = useState<string | null>("life_support");
  const [celebrationSkill, setCelebrationSkill] = useState<SkillDef | null>(null);

  const myCompletions = useMemo(() => {
    return (completions as any[]).filter((c: any) => c.userId === userId);
  }, [completions, userId]);

  const completedSkillIds = useMemo(() => {
    return new Set(myCompletions.map((c: any) => c.skillId));
  }, [myCompletions]);

  const totalXP = useMemo(() => {
    let xp = 0;
    for (const cat of SKILL_CATEGORIES) {
      for (const skill of cat.skills) {
        if (completedSkillIds.has(skill.id)) xp += skill.xp;
      }
    }
    return xp;
  }, [completedSkillIds]);

  const allSkillsCount = SKILL_CATEGORIES.reduce((sum, c) => sum + c.skills.length, 0);
  const completedCount = completedSkillIds.size;

  const rank = getRank(totalXP);
  const nextRank = getNextRank(totalXP);
  const RankIcon = rank.icon;

  const handleToggleSkill = (skill: SkillDef) => {
    if (completedSkillIds.has(skill.id)) {
      uncompleteSkill.mutate({ familyId, userId, skillId: skill.id });
    } else {
      completeSkill.mutate({ familyId, userId, skillId: skill.id });
      setCelebrationSkill(skill);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-purple-50 via-white to-green-50 pb-32">
      <Header />

      <div className="max-w-md mx-auto px-4 pt-4 space-y-5">
        <div className="text-center">
          <h2 className="text-xl font-black text-purple-800" data-testid="text-skill-tree-title">
            スキル図鑑
          </h2>
          <p className="text-xs text-purple-500 mt-1">育児スキルを習得してランクアップ</p>
        </div>

        <Card className="p-5 rounded-3xl border-purple-100 bg-gradient-to-br from-purple-50 to-white">
          <div className="flex items-center gap-4">
            <div className="w-16 h-16 rounded-2xl bg-gradient-to-br from-purple-200 to-purple-100 flex items-center justify-center">
              <RankIcon className="w-8 h-8 text-purple-600" />
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-2">
                <span className="text-lg font-black text-purple-800" data-testid="text-rank-name">{rank.name}</span>
                <span className="text-xs font-bold text-purple-500 bg-purple-100 px-2 py-0.5 rounded-full">{totalXP} XP</span>
              </div>
              <p className="text-xs text-purple-500 mt-1">
                {completedCount}/{allSkillsCount} スキル習得済み
              </p>
              {nextRank && (
                <div className="mt-2">
                  <div className="flex items-center justify-between mb-1">
                    <span className="text-[10px] text-purple-400">次のランク: {nextRank.name}</span>
                    <span className="text-[10px] text-purple-400">{nextRank.minXP - totalXP} XP</span>
                  </div>
                  <div className="h-2 bg-purple-100 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-purple-400 to-purple-600 rounded-full transition-all duration-500"
                      style={{
                        width: `${Math.min(100, ((totalXP - (RANK_THRESHOLDS[RANK_THRESHOLDS.indexOf(rank)].minXP)) / (nextRank.minXP - RANK_THRESHOLDS[RANK_THRESHOLDS.indexOf(rank)].minXP)) * 100)}%`,
                      }}
                    />
                  </div>
                </div>
              )}
            </div>
          </div>
          <div className="flex gap-2 mt-3">
            <Button
              variant={userId === "papa" ? "default" : "outline"}
              className="flex-1 rounded-2xl text-xs font-bold"
              onClick={() => localStorage.setItem("userType", "papa")}
              data-testid="button-switch-papa"
            >
              パパ
            </Button>
            <Button
              variant={userId === "mama" ? "default" : "outline"}
              className="flex-1 rounded-2xl text-xs font-bold"
              onClick={() => localStorage.setItem("userType", "mama")}
              data-testid="button-switch-mama"
            >
              ママ
            </Button>
          </div>
        </Card>

        {SKILL_CATEGORIES.map((cat) => {
          const isExpanded = expandedCategory === cat.id;
          const catCompleted = cat.skills.filter((s) => completedSkillIds.has(s.id)).length;
          const CatIcon = cat.icon;

          return (
            <Card key={cat.id} className="rounded-3xl border-gray-100 overflow-visible" data-testid={`card-category-${cat.id}`}>
              <button
                onClick={() => setExpandedCategory(isExpanded ? null : cat.id)}
                className="w-full p-4 flex items-center gap-3 text-left"
                data-testid={`button-toggle-${cat.id}`}
              >
                <div className={cn("w-10 h-10 rounded-2xl flex items-center justify-center", cat.bgColor)}>
                  <CatIcon className={cn("w-5 h-5", cat.color)} />
                </div>
                <div className="flex-1">
                  <div className="flex items-center gap-2">
                    <span className="text-sm font-bold text-gray-800">{cat.title}</span>
                    <span className="text-[10px] font-bold text-gray-400 bg-gray-100 px-2 py-0.5 rounded-full">
                      {catCompleted}/{cat.skills.length}
                    </span>
                  </div>
                  <div className="h-1.5 bg-gray-100 rounded-full mt-2 overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-purple-400 to-purple-500 rounded-full transition-all duration-500"
                      style={{ width: `${(catCompleted / cat.skills.length) * 100}%` }}
                    />
                  </div>
                </div>
                {isExpanded ? (
                  <ChevronUp className="w-4 h-4 text-gray-400" />
                ) : (
                  <ChevronDown className="w-4 h-4 text-gray-400" />
                )}
              </button>

              <AnimatePresence>
                {isExpanded && (
                  <motion.div
                    initial={{ height: 0, opacity: 0 }}
                    animate={{ height: "auto", opacity: 1 }}
                    exit={{ height: 0, opacity: 0 }}
                    transition={{ duration: 0.2 }}
                    className="overflow-hidden"
                  >
                    <div className="px-4 pb-4 space-y-3">
                      {cat.skills.map((skill) => {
                        const isCompleted = completedSkillIds.has(skill.id);
                        return (
                          <motion.div
                            key={skill.id}
                            layout
                            className={cn(
                              "p-4 rounded-2xl border-2 transition-all duration-300",
                              isCompleted
                                ? "border-purple-200 bg-purple-50/50"
                                : "border-gray-100 bg-white"
                            )}
                            data-testid={`skill-item-${skill.id}`}
                          >
                            <div className="flex items-start gap-3">
                              <button
                                onClick={() => handleToggleSkill(skill)}
                                className={cn(
                                  "w-8 h-8 rounded-xl flex items-center justify-center shrink-0 transition-all duration-300 mt-0.5",
                                  isCompleted
                                    ? "bg-purple-500 text-white"
                                    : "bg-gray-100 text-gray-400"
                                )}
                                data-testid={`button-skill-${skill.id}`}
                              >
                                {isCompleted ? (
                                  <Award className="w-4 h-4" />
                                ) : (
                                  <div className="w-3 h-3 rounded-full border-2 border-gray-300" />
                                )}
                              </button>
                              <div className="flex-1 min-w-0">
                                <div className="flex items-center gap-2 flex-wrap">
                                  <span className={cn("text-[10px] font-bold px-2 py-0.5 rounded-full", LEVEL_COLORS[skill.level])}>
                                    {skill.level}
                                  </span>
                                  <span className={cn("text-sm font-bold", isCompleted ? "text-purple-700" : "text-gray-800")}>
                                    {skill.title}
                                  </span>
                                  <span className="text-[10px] font-bold text-amber-600 bg-amber-50 px-2 py-0.5 rounded-full">
                                    {skill.xp} XP
                                  </span>
                                </div>
                                <p className="text-xs text-gray-500 mt-1 leading-relaxed">{skill.condition}</p>
                              </div>
                            </div>
                          </motion.div>
                        );
                      })}
                    </div>
                  </motion.div>
                )}
              </AnimatePresence>
            </Card>
          );
        })}
      </div>

      <AnimatePresence>
        {celebrationSkill && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[100] flex items-center justify-center bg-black/40 p-6"
            onClick={() => setCelebrationSkill(null)}
          >
            <motion.div
              initial={{ scale: 0.8, y: 20 }}
              animate={{ scale: 1, y: 0 }}
              exit={{ scale: 0.8, y: 20 }}
              onClick={(e) => e.stopPropagation()}
              className="bg-white rounded-[32px] p-6 max-w-sm w-full shadow-2xl"
              data-testid="dialog-celebration"
            >
              <div className="flex justify-end">
                <Button
                  size="icon"
                  variant="ghost"
                  onClick={() => setCelebrationSkill(null)}
                  data-testid="button-close-celebration"
                >
                  <X className="w-4 h-4" />
                </Button>
              </div>
              <div className="text-center space-y-4">
                <div className="w-20 h-20 rounded-full bg-gradient-to-br from-purple-200 to-amber-100 flex items-center justify-center mx-auto">
                  <Award className="w-10 h-10 text-purple-600" />
                </div>
                <div>
                  <h3 className="text-lg font-black text-purple-800">スキル習得！</h3>
                  <p className="text-base font-bold text-purple-600 mt-1">{celebrationSkill.title}</p>
                  <p className="text-sm font-bold text-amber-600 mt-1">+{celebrationSkill.xp} XP</p>
                </div>

                <div className="bg-purple-50 rounded-2xl p-4">
                  {celebrationSkill.takaMessage && (
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 rounded-full bg-green-100 flex items-center justify-center shrink-0">
                        <Zap className="w-5 h-5 text-green-600" />
                      </div>
                      <div>
                        <p className="text-[10px] font-bold text-green-600 mb-1">タカ先生</p>
                        <p className="text-xs text-purple-700 leading-relaxed font-medium">{celebrationSkill.takaMessage}</p>
                      </div>
                    </div>
                  )}
                  {celebrationSkill.mioMessage && (
                    <div className="flex items-start gap-3">
                      <div className="w-10 h-10 rounded-full bg-purple-100 flex items-center justify-center shrink-0">
                        <Sparkles className="w-5 h-5 text-purple-600" />
                      </div>
                      <div>
                        <p className="text-[10px] font-bold text-purple-600 mb-1">みおさん</p>
                        <p className="text-xs text-purple-700 leading-relaxed font-medium">{celebrationSkill.mioMessage}</p>
                      </div>
                    </div>
                  )}
                </div>

                <Button
                  onClick={() => setCelebrationSkill(null)}
                  className="w-full rounded-2xl h-12 font-bold"
                  data-testid="button-close-celebration-ok"
                >
                  やったね！
                </Button>
              </div>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <BottomNav />
    </div>
  );
}

