import { Input } from "@/components/ui/input";
import { Checkbox } from "@/components/ui/checkbox";
import { Label } from "@/components/ui/label";

const POOP_COLORS = [
  { id: "yellow", label: "黄色", color: "bg-yellow-400" },
  { id: "green", label: "緑色", color: "bg-green-500" },
  { id: "brown", label: "茶色", color: "bg-amber-700" },
  { id: "black", label: "黒色", color: "bg-gray-800" },
  { id: "white", label: "白色", color: "bg-gray-100 border border-gray-300" },
  { id: "red", label: "赤色", color: "bg-red-500" },
];

const POOP_CONSISTENCY = [
  { id: "normal", label: "普通" },
  { id: "hard", label: "硬い" },
  { id: "soft", label: "軟らかい" },
  { id: "watery", label: "水っぽい" },
];

const SYMPTOM_OPTIONS = [
  { id: "cough", label: "咳" },
  { id: "runny_nose", label: "鼻水" },
  { id: "rash", label: "湿疹" },
  { id: "vomit", label: "嘔吐" },
  { id: "diarrhea", label: "下痢" },
  { id: "fever", label: "発熱" },
];

export function QuickActions() {
  const { mutate, isPending } = useCreateLog();
  const familyId = localStorage.getItem("familyId") || "default";
  const { data: settings } = useSettings(familyId);
  const [activeDialog, setActiveDialog] = useState<string | null>(null);

  const [foodItems, setFoodItems] = useState("");
  const [foodAmount, setFoodAmount] = useState("");
  const [isNewFood, setIsNewFood] = useState(false);
  const [milestone, setMilestone] = useState("");

  const [diaperStep, setDiaperStep] = useState<"type" | "detail">("type");
  const [selectedDiaperType, setSelectedDiaperType] = useState("");
  const [poopColor, setPoopColor] = useState("");
  const [poopConsistency, setPoopConsistency] = useState("");

  const [bodyTemp, setBodyTemp] = useState("");

  const [selectedSymptoms, setSelectedSymptoms] = useState<string[]>([]);
  const [symptomNote, setSymptomNote] = useState("");

  const [milkStep, setMilkStep] = useState<"type" | "detail">("type");
  const [selectedMilkType, setSelectedMilkType] = useState("");
  const [breastLeftMin, setBreastLeftMin] = useState(0);
  const [breastRightMin, setBreastRightMin] = useState(0);
  const [isExpressed, setIsExpressed] = useState(false);
  const [expressedMl, setExpressedMl] = useState(0);
  const [formulaMl, setFormulaMl] = useState(0);

  const [sleepStep, setSleepStep] = useState<"main" | "manual">("main");
  const [manualDuration, setManualDuration] = useState(30);
  const [sleepTimerMin, setSleepTimerMin] = useState(0);

  const { data: activeSession } = useActiveSleepSession(familyId);
  const startSleep = useStartSleepSession();
  const endSleep = useEndSleepSession();
  const manualSleep = useManualSleepSession();

  useEffect(() => {
    if (!activeSession?.id || activeSession.endedAt) return;
    const update = () => {
      const mins = differenceInMinutes(new Date(), new Date(activeSession.startedAt));
      setSleepTimerMin(Math.max(0, mins));
    };
    update();
    const interval = setInterval(update, 10000);
    return () => clearInterval(interval);
  }, [activeSession]);

  const months = settings?.babyBirthday ? differenceInMonths(new Date(), parseISO(settings.babyBirthday)) : 0;
  const isTakaSensei = months >= 4;

  const actions = isTakaSensei ? [
    { 
      id: "food", 
      label: "離乳食", 
      icon: Utensils, 
      color: "bg-purple-50 text-purple-600 border-purple-100 hover:bg-purple-100",
      delay: 0.05,
    },
    { 
      id: "play", 
      label: "あそび", 
      icon: Footprints, 
      color: "bg-blue-50 text-blue-600 border-blue-100 hover:bg-blue-100",
      delay: 0.1,
      options: [
        { id: "tummy", label: "うつ伏せ練習", icon: "🐢", desc: "背筋を鍛える大事なトレーニングっす！" },
        { id: "peekaboo", label: "いないいないばあ", icon: "🙈", desc: "脳のトレーニング！笑顔が見たいっすね！" },
        { id: "rhythm", label: "お歌・リズム遊び", icon: "🎵", desc: "パパ・ママの歌声が一番のBGMっす！" },
        { id: "walk", label: "お散歩", icon: "🌳", desc: "外の刺激は五感を育てるっす！" },
        { id: "toy", label: "おもちゃ遊び", icon: "🧸", desc: "手先の器用さをアップさせるっす！" }
      ]
    },
    { 
      id: "diaper", 
      label: "おむつ", 
      icon: Baby, 
      color: "bg-amber-50 text-amber-600 border-amber-100 hover:bg-amber-100",
      delay: 0.15,
    },
    { 
      id: "sleep", 
      label: activeSession?.id && !activeSession.endedAt ? "起きた" : "ねんね", 
      icon: activeSession?.id && !activeSession.endedAt ? Sun : Moon, 
      color: activeSession?.id && !activeSession.endedAt 
        ? "bg-purple-50 text-purple-600 border-purple-200 hover:bg-purple-100"
        : "bg-indigo-50 text-indigo-500 border-indigo-100 hover:bg-indigo-100",
      delay: 0.2,
    },
    { 
      id: "milestone", 
      label: "はじめて", 
      icon: Star, 
      color: "bg-purple-50 text-purple-600 border-purple-100 hover:bg-purple-100",
      delay: 0.25,
    },
    {
      id: "thanks",
      label: "ありがとう",
      icon: Heart,
      color: "bg-red-50 text-red-500 border-red-100 hover:bg-red-100",
      delay: 0.3,
    }
  ] : [
    { 
      id: "milk", 
      label: "ミルク", 
      icon: Milk, 
      color: "bg-blue-50 text-blue-500 border-blue-100 hover:bg-blue-100",
      delay: 0.05,
    },
    { 
      id: "diaper", 
      label: "おむつ", 
      icon: Baby, 
      color: "bg-amber-50 text-amber-600 border-amber-100 hover:bg-amber-100",
      delay: 0.1,
    },
    { 
      id: "sleep", 
      label: activeSession?.id && !activeSession.endedAt ? "起きた" : "ねんね", 
      icon: activeSession?.id && !activeSession.endedAt ? Sun : Moon, 
      color: activeSession?.id && !activeSession.endedAt 
        ? "bg-purple-50 text-purple-600 border-purple-200 hover:bg-purple-100"
        : "bg-indigo-50 text-indigo-500 border-indigo-100 hover:bg-indigo-100",
      delay: 0.15,
    },
    { 
      id: "milestone", 
      label: "はじめて", 
      icon: Star, 
      color: "bg-purple-50 text-purple-600 border-purple-100 hover:bg-purple-100",
      delay: 0.2,
    },
    {
      id: "thanks",
      label: "ありがとう",
      icon: Heart,
      color: "bg-red-50 text-red-500 border-red-100 hover:bg-red-100",
      delay: 0.25,
    },
  ];

  const resetDiaper = () => {
    setDiaperStep("type");
    setSelectedDiaperType("");
    setPoopColor("");
    setPoopConsistency("");
  };

  const resetMilk = () => {
    setMilkStep("type");
    setSelectedMilkType("");
    setBreastLeftMin(0);
    setBreastRightMin(0);
    setIsExpressed(false);
    setExpressedMl(0);
    setFormulaMl(0);
  };

  const getMilkAiMessage = (mType: string, totalMl: number) => {
    if (isTakaSensei) {
      if (mType === "formula" || mType === "mixed") {
        return `タカ先生:「${totalMl}ml 完飲っす！ナイス飲みっぷり！これで午後のトレーニング（遊び）もバッチリっすね！」`;
      }
      return `タカ先生:「授乳おつかれっす！しっかり飲んでくれたみたいっすね！ママもパパもナイスアシストっす！」`;
    }
    if (mType === "breast" || mType === "mixed") {
      return `みお:「しっかり飲んでくれましたね。ママ、授乳の後は温かい飲み物で一息ついてくださいね。」`;
    }
    return `みお:「${totalMl}ml 飲めましたね。赤ちゃんのペースで大丈夫ですよ。」`;
  };

  const handleMilkSubmit = () => {
    const mType = selectedMilkType;
    const totalBreastMin = breastLeftMin + breastRightMin;
    const totalMl = (isExpressed ? expressedMl : 0) + formulaMl;

    let msgParts: string[] = [];
    if (mType === "breast" || mType === "mixed") {
      if (totalBreastMin > 0) {
        msgParts.push(`母乳 左${breastLeftMin}分/右${breastRightMin}分`);
      }
      if (isExpressed && expressedMl > 0) {
        msgParts.push(`搾乳 ${expressedMl}ml`);
      }
    }
    if (mType === "formula" || mType === "mixed") {
      msgParts.push(`ミルク ${formulaMl}ml`);
    }

    const typeLabel = mType === "breast" ? "母乳" : mType === "formula" ? "ミルク" : "混合";
    const msg = `${typeLabel}を記録しました！ ${msgParts.join(" / ")}`;

    mutate({
      type: "milk",
      subType: mType,
      message: msg,
      breastLeftMin: (mType === "breast" || mType === "mixed") ? breastLeftMin : null,
      breastRightMin: (mType === "breast" || mType === "mixed") ? breastRightMin : null,
      isExpressed: (mType === "breast" || mType === "mixed") ? isExpressed : false,
      expressedMl: (mType === "breast" || mType === "mixed") && isExpressed ? expressedMl : null,
      formulaMl: (mType === "formula" || mType === "mixed") ? formulaMl : null,
    });
    resetMilk();
    setActiveDialog(null);
  };

  const handleAction = (type: string, subType?: string, label?: string) => {
    let msg = label ? `${label}を記録しました！` : "クイックログ";

    if (type === "food") {
      msg = `${foodItems || '離乳食'}を${foodAmount || '記録'}しました！${isNewFood ? ' (新食材！)' : ''}`;
      mutate({ 
        type, 
        message: msg,
        foodItems,
        foodAmount,
        isNewFood
      });
      setFoodItems("");
      setFoodAmount("");
      setIsNewFood(false);
    } else if (type === "milestone") {
      mutate({
        type: "milestone",
        message: milestone || "はじめての記念日！",
      });
      setMilestone("");
    } else if (type === "diaper") {
      const dType = subType || selectedDiaperType;
      const colorLabel = poopColor ? POOP_COLORS.find(c => c.id === poopColor)?.label : "";
      const consistLabel = poopConsistency ? POOP_CONSISTENCY.find(c => c.id === poopConsistency)?.label : "";

      if (dType === "poop" || dType === "both") {
        msg = `${dType === "both" ? "両方" : "うんち"}を記録しました！${colorLabel ? `(${colorLabel}・${consistLabel || "普通"})` : ""}`;
      } else {
        msg = "おしっこを記録しました！";
      }

      mutate({
        type: "diaper",
        subType: dType || null,
        message: msg,
        poopColor: (dType === "poop" || dType === "both") ? poopColor || null : null,
        poopConsistency: (dType === "poop" || dType === "both") ? poopConsistency || null : null,
      });
      resetDiaper();
    } else {
      mutate({ 
        type, 
        subType: subType || null, 
        message: msg 
      });
    }
    setActiveDialog(null);
  };

  const handleDiaperTypeSelect = (dType: string) => {
    if (dType === "pee") {
      setSelectedDiaperType("pee");
      mutate({
        type: "diaper",
        subType: "pee",
        message: "おしっこを記録しました！",
      });
      setActiveDialog(null);
      resetDiaper();
    } else {
      setSelectedDiaperType(dType);
      setDiaperStep("detail");
    }
  };

  const openDialog = (id: string) => {
    if (id === "diaper") {
      resetDiaper();
    }
    if (id === "milk") {
      resetMilk();
    }
    setActiveDialog(id);
  };

  return (
    <div className="grid grid-cols-3 gap-3 px-6 w-full max-w-md mx-auto">
      {actions.map((action) => (
        <motion.button
          key={action.id}
          data-testid={`button-action-${action.id}`}
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: action.delay }}
          whileHover={{ scale: 1.05, y: -2 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => {
            if (action.id === "sleep") {
              if (activeSession?.id && !activeSession.endedAt) {
                endSleep.mutate(activeSession.id);
              } else {
                openDialog("sleep");
              }
            } else if (action.options || ["food", "milk", "diaper", "milestone"].includes(action.id)) {
              openDialog(action.id);
            } else {
              handleAction(action.id);
            }
          }}
          disabled={isPending || endSleep.isPending || startSleep.isPending}
          className={`
            flex flex-col items-center justify-center gap-2 py-4 px-2
            rounded-[2rem] border-2 shadow-sm transition-all duration-300
            ${action.color}
          `}
        >
          <div className="bg-white p-2.5 rounded-full shadow-sm">
            {(isPending || endSleep.isPending || startSleep.isPending) && action.id === "sleep" ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : isPending && !action.options && !["food", "milk", "diaper", "milestone", "sleep"].includes(action.id) ? (
              <Loader2 className="w-5 h-5 animate-spin" />
            ) : (
              <action.icon className="w-5 h-5 stroke-[2.5px]" />
            )}
          </div>
          <span className="font-bold text-xs tracking-wide">{action.label}</span>
          {action.id === "sleep" && activeSession?.id && !activeSession.endedAt && (
            <span className="text-[9px] font-black text-purple-600 -mt-1" data-testid="text-sleep-timer-mini">
              {sleepTimerMin}分
            </span>
          )}
        </motion.button>
      ))}

      <Dialog open={!!activeDialog} onOpenChange={() => { setActiveDialog(null); resetDiaper(); resetMilk(); setSleepStep("main"); }}>
        <DialogContent className="sm:max-w-md rounded-[2.5rem] border-none max-h-[85vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-xl font-black text-center">
              {activeDialog === "diaper" && diaperStep === "detail" 
                ? (selectedDiaperType === "poop" ? "うんちの詳細" : "両方の詳細")
                : activeDialog === "milk" && milkStep === "detail"
                ? (selectedMilkType === "breast" ? "母乳の記録" : selectedMilkType === "formula" ? "ミルクの記録" : "混合の記録")
                : activeDialog === "sleep" && sleepStep === "manual"
                ? "ねんねの手入力"
                : activeDialog === "sleep" ? "ねんねの記録" : actions.find(a => a.id === activeDialog)?.label}
            </DialogTitle>
          </DialogHeader>

          {activeDialog === "sleep" && sleepStep === "main" ? (
            <div className="space-y-3 py-4">
              <Button
                data-testid="button-sleep-start"
                onClick={() => {
                  const userId = localStorage.getItem("userType") || "papa";
                  startSleep.mutate({ familyId, createdBy: userId });
                  setActiveDialog(null);
                }}
                disabled={startSleep.isPending}
                className="w-full h-14 rounded-2xl bg-indigo-500 hover:bg-indigo-600 text-white font-black text-lg shadow-lg shadow-indigo-100"
              >
                <Moon className="w-5 h-5 mr-2" />
                寝た
              </Button>
              <Button
                data-testid="button-sleep-manual"
                variant="outline"
                onClick={() => setSleepStep("manual")}
                className="w-full h-14 rounded-2xl border-2 font-black text-base"
              >
                <Edit3 className="w-4 h-4 mr-2" />
                さっき寝てた（手入力）
              </Button>
              <div className="bg-indigo-50 rounded-xl p-3 border border-indigo-100">
                <p className="text-xs font-bold text-indigo-700">
                  {isTakaSensei
                    ? `タカ先生:「寝かしつけの準備っすか？タイマーで記録するっすよ！」`
                    : `みお:「おやすみの記録をつけましょう。寝たボタンで計測を始められますよ。」`}
                </p>
              </div>
            </div>

          ) : activeDialog === "sleep" && sleepStep === "manual" ? (
            <div className="space-y-4 py-4 px-2">
              <div className="space-y-2">
                <Label className="font-bold text-xs">何分寝ていましたか？</Label>
                <div className="flex items-center gap-3">
                  <Slider
                    data-testid="slider-manual-sleep"
                    value={[manualDuration]}
                    onValueChange={(v) => setManualDuration(v[0])}
                    max={180}
                    min={5}
                    step={5}
                    className="flex-1"
                  />
                  <span className="text-lg font-black w-16 text-right" data-testid="text-manual-duration">{manualDuration}分</span>
                </div>
                <div className="flex items-center gap-2 flex-wrap justify-center">
                  {[15, 30, 45, 60, 90, 120].map((m) => (
                    <Button
                      key={m}
                      variant="outline"
                      size="sm"
                      data-testid={`button-sleep-preset-${m}`}
                      onClick={() => setManualDuration(m)}
                      className={`rounded-xl border-2 font-bold text-xs ${manualDuration === m ? 'border-indigo-300 bg-indigo-50' : 'border-gray-100'}`}
                    >
                      {m}分
                    </Button>
                  ))}
                </div>
              </div>
              <div className="bg-indigo-50 rounded-xl p-3 border border-indigo-100">
                <p className="text-xs font-bold text-indigo-700">
                  {isTakaSensei
                    ? `タカ先生:「${manualDuration}分のお昼寝っすか？しっかり充電できたっすね！」`
                    : `みお:「${manualDuration}分よく眠れましたね。記録しておきますね。」`}
                </p>
              </div>
              <Button
                data-testid="button-sleep-manual-submit"
                onClick={() => {
                  const userId = localStorage.getItem("userType") || "papa";
                  const startedAt = subMinutes(new Date(), manualDuration).toISOString();
                  manualSleep.mutate({ familyId, createdBy: userId, durationMin: manualDuration, startedAt });
                  setSleepStep("main");
                  setActiveDialog(null);
                }}
                disabled={manualSleep.isPending}
                className="w-full h-14 rounded-2xl bg-indigo-500 hover:bg-indigo-600 text-white font-black text-base shadow-lg shadow-indigo-100"
              >
                {manualSleep.isPending ? <Loader2 className="w-5 h-5 animate-spin" /> : `${manualDuration}分を記録する`}
              </Button>
            </div>

          ) : activeDialog === "milk" && milkStep === "type" ? (
            <div className="grid grid-cols-3 gap-3 py-4">
              {[
                { id: "breast", label: "母乳", icon: "🤱" },
                { id: "formula", label: "ミルク", icon: "🍼" },
                { id: "mixed", label: "混合", icon: "➕" },
              ].map((opt) => (
                <Button
                  key={opt.id}
                  data-testid={`button-milk-${opt.id}`}
                  variant="outline"
                  onClick={() => { setSelectedMilkType(opt.id); setMilkStep("detail"); }}
                  className="h-24 rounded-2xl border-2 flex flex-col items-center justify-center gap-1 text-center p-2"
                >
                  <span className="text-2xl">{opt.icon}</span>
                  <span className="font-bold text-xs">{opt.label}</span>
                </Button>
              ))}
            </div>

          ) : activeDialog === "milk" && milkStep === "detail" ? (
            <div className="space-y-4 py-4 px-2">
              {(selectedMilkType === "breast" || selectedMilkType === "mixed") && (
                <>
                  <div className="space-y-3">
                    <Label className="font-bold text-xs">授乳時間</Label>
                    <div className="grid grid-cols-2 gap-3">
                      <div className="space-y-2">
                        <p className="text-[10px] font-bold text-gray-400 text-center">左</p>
                        <div className="flex items-center justify-center gap-2">
                          <Button
                            size="icon"
                            variant="outline"
                            data-testid="button-breast-left-minus"
                            onClick={() => setBreastLeftMin(v => Math.max(0, v - 1))}
                            className="rounded-xl border-2"
                          >
                            <Minus className="w-4 h-4" />
                          </Button>
                          <span className="text-2xl font-black w-10 text-center" data-testid="text-breast-left-min">{breastLeftMin}</span>
                          <Button
                            size="icon"
                            variant="outline"
                            data-testid="button-breast-left-plus"
                            onClick={() => setBreastLeftMin(v => Math.min(60, v + 1))}
                            className="rounded-xl border-2"
                          >
                            <Plus className="w-4 h-4" />
                          </Button>
                        </div>
                        <p className="text-[10px] text-gray-400 text-center">分</p>
                      </div>
                      <div className="space-y-2">
                        <p className="text-[10px] font-bold text-gray-400 text-center">右</p>
                        <div className="flex items-center justify-center gap-2">
                          <Button
                            size="icon"
                            variant="outline"
                            data-testid="button-breast-right-minus"
                            onClick={() => setBreastRightMin(v => Math.max(0, v - 1))}
                            className="rounded-xl border-2"
                          >
                            <Minus className="w-4 h-4" />
                          </Button>
                          <span className="text-2xl font-black w-10 text-center" data-testid="text-breast-right-min">{breastRightMin}</span>
                          <Button
                            size="icon"
                            variant="outline"
                            data-testid="button-breast-right-plus"
                            onClick={() => setBreastRightMin(v => Math.min(60, v + 1))}
                            className="rounded-xl border-2"
                          >
                            <Plus className="w-4 h-4" />
                          </Button>
                        </div>
                        <p className="text-[10px] text-gray-400 text-center">分</p>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 flex-wrap justify-center">
                      {[5, 10, 15, 20].map((m) => (
                        <Button
                          key={m}
                          variant="outline"
                          size="sm"
                          data-testid={`button-breast-preset-${m}`}
                          onClick={() => { setBreastLeftMin(m); setBreastRightMin(m); }}
                          className="rounded-xl border-2 font-bold text-xs"
                        >
                          各{m}分
                        </Button>
                      ))}
                    </div>
                  </div>

                  <div className="border-t pt-3 space-y-2">
                    <div className="flex items-center space-x-2 bg-blue-50 p-3 rounded-xl border border-blue-100">
                      <Checkbox
                        id="expressed"
                        data-testid="checkbox-expressed"
                        checked={isExpressed}
                        onCheckedChange={(checked) => setIsExpressed(!!checked)}
                      />
                      <Label htmlFor="expressed" className="text-sm font-bold text-blue-900 cursor-pointer">
                        搾乳した母乳をあげた
                      </Label>
                    </div>
                    {isExpressed && (
                      <div className="space-y-2">
                        <Label className="font-bold text-xs">搾乳量 (ml)</Label>
                        <div className="flex items-center gap-3">
                          <Slider
                            data-testid="slider-expressed-ml"
                            value={[expressedMl]}
                            onValueChange={(v) => setExpressedMl(v[0])}
                            max={200}
                            step={10}
                            className="flex-1"
                          />
                          <span className="text-lg font-black w-16 text-right" data-testid="text-expressed-ml">{expressedMl}ml</span>
                        </div>
                      </div>
                    )}
                  </div>
                </>
              )}

              {(selectedMilkType === "formula" || selectedMilkType === "mixed") && (
                <div className="space-y-2">
                  <Label className="font-bold text-xs">
                    {selectedMilkType === "mixed" ? "ミルクの量 (ml)" : "飲んだ量 (ml)"}
                  </Label>
                  <div className="flex items-center gap-3">
                    <Slider
                      data-testid="slider-formula-ml"
                      value={[formulaMl]}
                      onValueChange={(v) => setFormulaMl(v[0])}
                      max={300}
                      step={10}
                      className="flex-1"
                    />
                    <span className="text-lg font-black w-16 text-right" data-testid="text-formula-ml">{formulaMl}ml</span>
                  </div>
                  <div className="flex items-center gap-2 flex-wrap justify-center">
                    {[40, 60, 80, 100, 120, 160, 200].map((ml) => (
                      <Button
                        key={ml}
                        variant="outline"
                        size="sm"
                        data-testid={`button-formula-preset-${ml}`}
                        onClick={() => setFormulaMl(ml)}
                        className={`rounded-xl border-2 font-bold text-xs ${formulaMl === ml ? 'border-blue-300 bg-blue-50' : 'border-gray-100'}`}
                      >
                        {ml}ml
                      </Button>
                    ))}
                  </div>
                </div>
              )}

              <div className="bg-blue-50 rounded-xl p-3 border border-blue-100">
                <p className="text-xs font-bold text-blue-700">
                  {getMilkAiMessage(selectedMilkType, (isExpressed ? expressedMl : 0) + formulaMl)}
                </p>
              </div>

              <Button
                data-testid="button-milk-submit"
                onClick={handleMilkSubmit}
                disabled={
                  (selectedMilkType === "breast" && breastLeftMin === 0 && breastRightMin === 0 && !isExpressed) ||
                  (selectedMilkType === "formula" && formulaMl === 0) ||
                  (selectedMilkType === "mixed" && breastLeftMin === 0 && breastRightMin === 0 && !isExpressed && formulaMl === 0)
                }
                className="w-full h-14 rounded-2xl bg-blue-500 hover:bg-blue-600 text-white font-black text-lg shadow-lg shadow-blue-100"
              >
                記録する
              </Button>
            </div>

          ) : activeDialog === "food" ? (
            <div className="space-y-4 py-4 px-2">
              <div className="space-y-2">
                <Label className="font-bold text-xs">食べたもの</Label>
                <Input 
                  data-testid="input-food-items"
                  placeholder="例：10倍粥、にんじん" 
                  value={foodItems}
                  onChange={(e) => setFoodItems(e.target.value)}
                  className="rounded-xl border-2 focus:ring-purple-200"
                />
              </div>

              <div className="space-y-2">
                <Label className="font-bold text-xs">量</Label>
                <div className="grid grid-cols-2 gap-2">
                  {["完食", "半分", "ひと口", "拒否"].map((amount) => (
                    <Button
                      key={amount}
                      data-testid={`button-food-${amount}`}
                      variant={foodAmount === amount ? "default" : "outline"}
                      onClick={() => setFoodAmount(amount)}
                      className={`rounded-xl border-2 font-bold ${foodAmount === amount ? 'bg-purple-500 border-purple-500' : 'border-gray-100'}`}
                    >
                      {amount}
                    </Button>
                  ))}
                </div>
              </div>

              <div className="flex items-center space-x-2 bg-purple-50 p-3 rounded-xl border border-purple-100">
                <Checkbox 
                  id="new-food" 
                  checked={isNewFood} 
                  onCheckedChange={(checked) => setIsNewFood(!!checked)}
                />
                <Label htmlFor="new-food" className="text-sm font-bold text-purple-900 cursor-pointer">
                  初めて食べた食材
                </Label>
              </div>

              <Button 
                data-testid="button-food-submit"
                onClick={() => handleAction("food")}
                disabled={!foodAmount}
                className="w-full h-14 rounded-2xl bg-purple-500 hover:bg-purple-600 text-white font-black text-lg shadow-lg shadow-purple-100"
              >
                記録する
              </Button>
            </div>

          ) : activeDialog === "diaper" && diaperStep === "type" ? (
            <div className="grid grid-cols-3 gap-3 py-4">
              {[
                { id: "pee", label: "おしっこ", icon: "💧" },
                { id: "poop", label: "うんち", icon: "💩" },
                { id: "both", label: "両方", icon: "✨" },
              ].map((opt) => (
                <Button
                  key={opt.id}
                  data-testid={`button-diaper-${opt.id}`}
                  variant="outline"
                  onClick={() => handleDiaperTypeSelect(opt.id)}
                  className="h-24 rounded-2xl border-2 flex flex-col items-center justify-center gap-1 text-center p-2"
                >
                  <span className="text-2xl">{opt.icon}</span>
                  <span className="font-bold text-xs">{opt.label}</span>
                </Button>
              ))}
            </div>

          ) : activeDialog === "diaper" && diaperStep === "detail" ? (
            <div className="space-y-4 py-4 px-2">
              <div className="space-y-2">
                <Label className="font-bold text-xs">うんちの色</Label>
                <div className="grid grid-cols-3 gap-2">
                  {POOP_COLORS.map((c) => (
                    <Button
                      key={c.id}
                      data-testid={`button-poop-color-${c.id}`}
                      variant="outline"
                      onClick={() => setPoopColor(c.id)}
                      className={`h-14 rounded-xl border-2 flex flex-col items-center justify-center gap-1 ${poopColor === c.id ? 'border-amber-400 bg-amber-50' : 'border-gray-100'}`}
                    >
                      <div className={`w-5 h-5 rounded-full ${c.color}`} />
                      <span className="text-[10px] font-bold">{c.label}</span>
                    </Button>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <Label className="font-bold text-xs">形状</Label>
                <div className="grid grid-cols-2 gap-2">
                  {POOP_CONSISTENCY.map((c) => (
                    <Button
                      key={c.id}
                      data-testid={`button-poop-consistency-${c.id}`}
                      variant={poopConsistency === c.id ? "default" : "outline"}
                      onClick={() => setPoopConsistency(c.id)}
                      className={`rounded-xl border-2 font-bold ${poopConsistency === c.id ? 'bg-amber-500 border-amber-500' : 'border-gray-100'}`}
                    >
                      {c.label}
                    </Button>
                  ))}
                </div>
              </div>

              <Button
                data-testid="button-diaper-submit"
                onClick={() => handleAction("diaper")}
                className="w-full h-14 rounded-2xl bg-amber-500 hover:bg-amber-600 text-white font-black text-lg shadow-lg shadow-amber-100"
              >
                記録する
              </Button>
            </div>

          ) : activeDialog === "milestone" ? (
            <div className="space-y-4 py-4 px-2">
              <div className="space-y-2">
                <Label className="font-bold text-xs">記念日の内容</Label>
                <Input 
                  data-testid="input-milestone"
                  placeholder="例：はじめて寝返りした！" 
                  value={milestone}
                  onChange={(e) => setMilestone(e.target.value)}
                  className="rounded-xl border-2 focus:ring-purple-200"
                />
              </div>
              <Button 
                data-testid="button-milestone-submit"
                onClick={() => handleAction("milestone")}
                disabled={!milestone}
                className="w-full h-14 rounded-2xl bg-purple-500 hover:bg-purple-600 text-white font-black text-lg shadow-lg shadow-purple-100"
              >
                記録する
              </Button>
            </div>
          ) : (
            <div className="grid grid-cols-2 gap-3 py-4">
              {activeDialog && actions.find(a => a.id === activeDialog)?.options?.map((opt) => (
                <Button
                  key={opt.id}
                  data-testid={`button-option-${opt.id}`}
                  variant="outline"
                  onClick={() => handleAction(activeDialog, opt.id, opt.label)}
                  className="h-24 rounded-2xl border-2 flex flex-col items-center justify-center gap-1 hover:bg-purple-50 hover:border-purple-200 text-center p-2"
                >
                  <span className="text-2xl">{opt.icon}</span>
                  <span className="font-bold text-xs">{opt.label}</span>
                </Button>
              ))}
            </div>
          )}
        </DialogContent>
      </Dialog>
    </div>
  );
}

client/src/pages/Onboarding.tsx.content:
import { useState } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { Grape, User, Crown, ChevronRight, Cake, Baby } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useUpdateSettings } from "@/hooks/use-app-data";

interface OnboardingProps {
  onComplete: () => void;
}

export default function Onboarding({ onComplete }: OnboardingProps) {
  const [step, setStep] = useState(0);
  const [babyName, setBabyName] = useState("");
  const [babyBirthday, setBabyBirthday] = useState("");
  const [userType, setUserType] = useState<"papa" | "mama" | "">("");
  const { mutate, isPending } = useUpdateSettings();

  const handleFinish = () => {
    const familyId = `family-${Date.now().toString(36)}`;
    localStorage.setItem("familyId", familyId);
    localStorage.setItem("userType", userType);
    localStorage.setItem("onboarding_done", "true");

    mutate(
      {
        familyId,
        babyName: babyName || "赤ちゃん",
        babyBirthday: babyBirthday || undefined,
        currentCaregiver: userType === "papa" ? "パパ" : "ママ",
      },
      {
        onSettled: () => onComplete(),
      }
    );
  };

  return (
    <div className="fixed inset-0 z-[100] bg-gradient-to-br from-purple-50 via-white to-green-50 overflow-auto">
      <div className="max-w-md mx-auto min-h-screen flex flex-col items-center justify-center px-8 py-12">
        <AnimatePresence mode="wait">
          {step === 0 && (
            <motion.div
              key="welcome"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col items-center text-center w-full"
            >
              <div className="w-28 h-28 rounded-full bg-gradient-to-br from-purple-100 to-green-50 flex items-center justify-center shadow-lg border-4 border-white mb-6">
                <Grape className="w-14 h-14 text-purple-500" />
              </div>
              <h1 className="text-3xl font-black text-purple-700 tracking-tight mb-2" data-testid="text-onboarding-title">
                ペア育
              </h1>
              <p className="text-sm font-bold text-purple-400 mb-6">
                ふたりで育てる、ふたりで楽しむ
              </p>
              <div className="w-12 h-px bg-purple-200 mb-4" />
              <p className="text-[10px] font-bold text-purple-300 tracking-widest uppercase mb-1">
                Produced by
              </p>
              <p className="text-sm font-black text-purple-500 mb-8">
                産前産後ケアホテル ぶどうの木
              </p>
              <div className="bg-white/80 backdrop-blur-sm rounded-3xl p-6 border-2 border-purple-100 shadow-sm w-full mb-8">
                <p className="text-base font-bold text-purple-700 leading-relaxed">
                  最強のチーム作りを
                  <br />
                  サポートします
                </p>
                <p className="text-xs text-gray-500 mt-3 leading-relaxed">
                  育児の記録・共有・振り返りを通じて、パパとママが最高のチームになるためのアプリです。
                </p>
              </div>
              <Button
                onClick={() => setStep(1)}
                className="w-full h-14 rounded-2xl text-lg font-black shadow-lg"
                data-testid="button-onboarding-start"
              >
                はじめる
                <ChevronRight className="w-5 h-5 ml-1" />
              </Button>
            </motion.div>
          )}

          {step === 1 && (
            <motion.div
              key="baby"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col items-center w-full"
            >
              <div className="w-20 h-20 rounded-full bg-purple-100 flex items-center justify-center mb-6">
                <Baby className="w-10 h-10 text-purple-500" />
              </div>
              <h2 className="text-2xl font-black text-gray-800 mb-2">赤ちゃんの情報</h2>
              <p className="text-sm text-gray-500 mb-8">アプリの主役を教えてください</p>

              <div className="w-full space-y-5">
                <div>
                  <Label htmlFor="ob-name" className="text-sm font-bold text-gray-600 mb-1.5 block">
                    お名前
                  </Label>
                  <Input
                    id="ob-name"
                    value={babyName}
                    onChange={(e) => setBabyName(e.target.value)}
                    className="rounded-xl border-2 border-gray-100 h-12 text-lg"
                    placeholder="例: はなちゃん、りくくん"
                    data-testid="input-onboarding-baby-name"
                  />
                </div>
                <div>
                  <Label htmlFor="ob-birthday" className="text-sm font-bold text-gray-600 mb-1.5 flex items-center gap-1.5">
                    <Cake className="w-4 h-4 text-purple-400" />
                    <span>生年月日</span>
                  </Label>
                  <Input
                    id="ob-birthday"
                    type="date"
                    value={babyBirthday}
                    onChange={(e) => setBabyBirthday(e.target.value)}
                    className="rounded-xl border-2 border-gray-100 h-12 text-lg"
                    data-testid="input-onboarding-birthday"
                  />
                </div>
              </div>

              <Button
                onClick={() => setStep(2)}
                disabled={!babyName}
                className="w-full h-14 rounded-2xl text-lg font-black shadow-lg mt-8"
                data-testid="button-onboarding-next"
              >
                次へ
                <ChevronRight className="w-5 h-5 ml-1" />
              </Button>
            </motion.div>
          )}

          {step === 2 && (
            <motion.div
              key="role"
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -20 }}
              className="flex flex-col items-center w-full"
            >
              <h2 className="text-2xl font-black text-gray-800 mb-2">あなたの役割</h2>
              <p className="text-sm text-gray-500 mb-8">どちらで参加しますか？</p>

              <div className="grid grid-cols-2 gap-4 w-full mb-8">
                <button
                  onClick={() => setUserType("papa")}
                  className={`flex flex-col items-center justify-center py-8 rounded-3xl border-2 transition-all duration-300 ${
                    userType === "papa"
                      ? "border-purple-400 bg-purple-50 shadow-lg scale-[1.02]"
                      : "border-gray-100 bg-white hover:border-purple-200"
                  }`}
                  data-testid="button-onboarding-papa"
                >
                  <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-3 ${
                    userType === "papa" ? "bg-purple-200" : "bg-gray-100"
                  }`}>
                    <User className={`w-8 h-8 ${userType === "papa" ? "text-purple-600" : "text-gray-400"}`} />
                  </div>
                  <span className={`text-lg font-black ${userType === "papa" ? "text-purple-700" : "text-gray-600"}`}>
                    パパ
                  </span>
                </button>

                <button
                  onClick={() => setUserType("mama")}
                  className={`flex flex-col items-center justify-center py-8 rounded-3xl border-2 transition-all duration-300 ${
                    userType === "mama"
                      ? "border-pink-400 bg-pink-50 shadow-lg scale-[1.02]"
                      : "border-gray-100 bg-white hover:border-pink-200"
                  }`}
                  data-testid="button-onboarding-mama"
                >
                  <div className={`w-16 h-16 rounded-full flex items-center justify-center mb-3 ${
                    userType === "mama" ? "bg-pink-200" : "bg-gray-100"
                  }`}>
                    <Crown className={`w-8 h-8 ${userType === "mama" ? "text-pink-600" : "text-gray-400"}`} />
                  </div>
                  <span className={`text-lg font-black ${userType === "mama" ? "text-pink-700" : "text-gray-600"}`}>
                    ママ
                  </span>
                </button>
              </div>

              <Button
                onClick={handleFinish}
                disabled={!userType || isPending}
                className="w-full h-14 rounded-2xl text-lg font-black shadow-lg"
                data-testid="button-onboarding-finish"
              >
                {isPending ? "登録中..." : "ペア育をはじめる"}
              </Button>
            </motion.div>
          )}
        </AnimatePresence>

        <div className="flex gap-2 mt-8">
          {[0, 1, 2].map((i) => (
            <div
              key={i}
              className={`w-2.5 h-2.5 rounded-full transition-all duration-300 ${
                i === step ? "bg-purple-500 scale-125" : "bg-purple-200"
              }`}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

client/src/components/Navigation.tsx.content:
import { Link, useLocation } from "wouter";
import { Home, Settings, CalendarDays, Gift, Grape } from "lucide-react";
import { cn } from "@/lib/utils";

export function BottomNav() {
  const [location] = useLocation();

  const navItems = [
    { href: "/", icon: Home, label: "ホーム" },
    { href: "/calendar", icon: CalendarDays, label: "カレンダー" },
    { href: "/shop", icon: Gift, label: "ご褒美" },
    { href: "/settings", icon: Settings, label: "設定" },
  ];

  return (
    <nav className="fixed bottom-0 left-0 right-0 z-50 bg-white/90 backdrop-blur-lg border-t border-purple-100 shadow-lg shadow-purple-900/5 pb-safe">
      <div className="flex items-center justify-center pt-1">
        <div className="flex items-center gap-1" data-testid="brand-footer">
          <Grape className="w-2.5 h-2.5 text-purple-300" />
          <span className="text-[8px] font-bold text-purple-300 tracking-wider">
            Produced by ぶどうの木
          </span>
        </div>
      </div>
      <div className="flex justify-around items-center h-18 max-w-md mx-auto px-4 pb-1">
        {navItems.map((item) => {
          const isActive = location === item.href;
          return (
            <Link key={item.href} href={item.href} className="flex-1">
              <div 
                className={cn(
                  "flex flex-col items-center justify-center space-y-1 py-2 rounded-2xl transition-all duration-300",
                  isActive 
                    ? "text-primary transform -translate-y-1" 
                    : "text-muted-foreground hover:text-purple-400"
                )}
              >
                <div className={cn(
                  "p-2 rounded-2xl transition-all duration-300",
                  isActive ? "bg-purple-50" : "bg-transparent"
                )}>
                  <item.icon className={cn("w-6 h-6", isActive ? "stroke-[2.5px]" : "stroke-2")} />
                </div>
                <span className="text-[10px] font-bold tracking-wide">{item.label}</span>
              </div>
            </Link>
          );
        })}
      </div>
    </nav>
  );
}

