import { useState, useMemo } from "react";
import { useLocation } from "wouter";
import {
  ArrowLeft, TrendingUp, Thermometer, Baby, Stethoscope,
  Plus, Loader2, Ruler, Weight, CircleDot, Activity,
} from "lucide-react";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { BottomNav } from "@/components/Navigation";
import { useLogs, useSettings, useGrowthRecords, useCreateGrowthRecord } from "@/hooks/use-app-data";
import { differenceInMonths, parseISO, format } from "date-fns";
import { ja } from "date-fns/locale";
import {
  LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer,
} from "recharts";

const SYMPTOM_LABELS: Record<string, string> = {
  cough: "咳",
  runny_nose: "鼻水",
  rash: "湿疹",
  vomit: "嘔吐",
  diarrhea: "下痢",
  fever: "発熱",
};

const POOP_COLOR_LABELS: Record<string, string> = {
  yellow: "黄色",
  green: "緑色",
  brown: "茶色",
  black: "黒色",
  white: "白色",
  red: "赤色",
};

const POOP_CONSIST_LABELS: Record<string, string> = {
  normal: "普通",
  hard: "硬い",
  soft: "軟らかい",
  watery: "水っぽい",
};

export default function Health() {
  const [, navigate] = useLocation();
  const familyId = localStorage.getItem("familyId") || "default";
  const { data: settings } = useSettings(familyId);
  const { data: logs, isLoading: logsLoading } = useLogs(familyId);
  const { data: growthRecords, isLoading: growthLoading } = useGrowthRecords(familyId);
  const createGrowth = useCreateGrowthRecord();

  const [activeTab, setActiveTab] = useState<"health" | "growth">("health");
  const [showGrowthForm, setShowGrowthForm] = useState(false);
  const [weightG, setWeightG] = useState("");
  const [heightCm, setHeightCm] = useState("");
  const [headCm, setHeadCm] = useState("");
  const [measuredDate, setMeasuredDate] = useState(format(new Date(), "yyyy-MM-dd"));

  const months = settings?.babyBirthday ? differenceInMonths(new Date(), parseISO(settings.babyBirthday)) : 0;
  const isTakaSensei = months >= 4;

  const healthLogs = useMemo(() => {
    if (!logs) return [];
    const now = new Date();
    const h24ago = new Date(now.getTime() - 24 * 60 * 60 * 1000);
    return logs
      .filter((l: any) => {
        const t = new Date(l.createdAt);
        return t >= h24ago && ["diaper", "temp", "symptom"].includes(l.type);
      })
      .sort((a: any, b: any) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [logs]);

  const sortedGrowth = useMemo(() => {
    if (!growthRecords || growthRecords.length === 0) return [];
    return [...growthRecords].sort((a: any, b: any) => 
      new Date(a.measuredAt).getTime() - new Date(b.measuredAt).getTime()
    );
  }, [growthRecords]);

  const growthChartData = useMemo(() => {
    if (sortedGrowth.length === 0) return [];
    return sortedGrowth.map((r: any) => ({
      date: format(parseISO(r.measuredAt), "M/d"),
      weight: r.weightGrams ? r.weightGrams / 1000 : null,
      height: r.heightCm || null,
      head: r.headCircumferenceCm || null,
    }));
  }, [sortedGrowth]);

  const latestGrowth = sortedGrowth.length > 0
    ? sortedGrowth[sortedGrowth.length - 1]
    : null;
  const prevGrowth = sortedGrowth.length > 1
    ? sortedGrowth[sortedGrowth.length - 2]
    : null;

  const weightGain = latestGrowth?.weightGrams && prevGrowth?.weightGrams
    ? latestGrowth.weightGrams - prevGrowth.weightGrams
    : null;

  const handleGrowthSubmit = () => {
    if (!weightG && !heightCm && !headCm) return;
    const userId = localStorage.getItem("userType") || "papa";
    const data: any = { familyId, userId, measuredAt: measuredDate };
    if (weightG) data.weightGrams = parseInt(weightG);
    if (heightCm) data.heightCm = parseFloat(heightCm);
    if (headCm) data.headCircumferenceCm = parseFloat(headCm);

    createGrowth.mutate(data, {
      onSuccess: () => {
        setShowGrowthForm(false);
        setWeightG("");
        setHeightCm("");
        setHeadCm("");
      },
    });
  };

  const isLoading = logsLoading || growthLoading;

  if (isLoading) {
    return (
      <div className="min-h-screen bg-gradient-to-b from-purple-50 via-white to-green-50 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-purple-400" />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-b from-purple-50 via-white to-green-50 pb-24">
      <div className="sticky top-0 z-40 bg-white/80 backdrop-blur-lg border-b border-purple-100">
        <div className="max-w-md mx-auto flex items-center gap-3 px-4 py-3">
          <Button
            data-testid="button-health-back"
            variant="ghost"
            size="icon"
            onClick={() => navigate("/")}
            className="rounded-full"
          >
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <h1 className="text-lg font-black">
            {settings?.babyName || "赤ちゃん"}の健康・成長
          </h1>
        </div>
      </div>

      <div className="max-w-md mx-auto px-4 pt-4 space-y-4">
        <div className="flex gap-2">
          <Button
            data-testid="tab-health"
            variant={activeTab === "health" ? "default" : "outline"}
            onClick={() => setActiveTab("health")}
            className={`flex-1 rounded-2xl font-bold ${activeTab === "health" ? "bg-teal-500 hover:bg-teal-600" : ""}`}
          >
            <Activity className="w-4 h-4 mr-1" />
            健康ログ
          </Button>
          <Button
            data-testid="tab-growth"
            variant={activeTab === "growth" ? "default" : "outline"}
            onClick={() => setActiveTab("growth")}
            className={`flex-1 rounded-2xl font-bold ${activeTab === "growth" ? "bg-green-500 hover:bg-green-600" : ""}`}
          >
            <TrendingUp className="w-4 h-4 mr-1" />
            成長曲線
          </Button>
        </div>

        {activeTab === "health" ? (
          <HealthLogTab
            healthLogs={healthLogs}
            isTakaSensei={isTakaSensei}
            months={months}
          />
        ) : (
          <GrowthTab
            growthChartData={growthChartData}
            latestGrowth={latestGrowth}
            weightGain={weightGain}
            isTakaSensei={isTakaSensei}
            onAddGrowth={() => setShowGrowthForm(true)}
          />
        )}
      </div>

      <Dialog open={showGrowthForm} onOpenChange={setShowGrowthForm}>
        <DialogContent className="sm:max-w-md rounded-[2.5rem] border-none">
          <DialogHeader>
            <DialogTitle className="text-xl font-black text-center">
              身体測定を記録
            </DialogTitle>
          </DialogHeader>
          <div className="space-y-4 py-4 px-2">
            <div className="space-y-2">
              <Label className="font-bold text-xs">測定日</Label>
              <Input
                data-testid="input-growth-date"
                type="date"
                value={measuredDate}
                onChange={(e) => setMeasuredDate(e.target.value)}
                className="rounded-xl border-2"
              />
            </div>
            <div className="space-y-2">
              <Label className="font-bold text-xs flex items-center gap-1">
                <Weight className="w-3.5 h-3.5" /> 体重 (g)
              </Label>
              <Input
                data-testid="input-weight"
                type="number"
                placeholder="例: 6500"
                value={weightG}
                onChange={(e) => setWeightG(e.target.value)}
                className="rounded-xl border-2"
              />
            </div>
            <div className="space-y-2">
              <Label className="font-bold text-xs flex items-center gap-1">
                <Ruler className="w-3.5 h-3.5" /> 身長 (cm)
              </Label>
              <Input
                data-testid="input-height"
                type="number"
                step="0.1"
                placeholder="例: 65.0"
                value={heightCm}
                onChange={(e) => setHeightCm(e.target.value)}
                className="rounded-xl border-2"
              />
            </div>
            <div className="space-y-2">
              <Label className="font-bold text-xs flex items-center gap-1">
                <CircleDot className="w-3.5 h-3.5" /> 頭囲 (cm)
              </Label>
              <Input
                data-testid="input-head"
                type="number"
                step="0.1"
                placeholder="例: 42.0"
                value={headCm}
                onChange={(e) => setHeadCm(e.target.value)}
                className="rounded-xl border-2"
              />
            </div>
            <Button
              data-testid="button-growth-submit"
              onClick={handleGrowthSubmit}
              disabled={!weightG && !heightCm && !headCm}
              className="w-full h-14 rounded-2xl bg-green-500 hover:bg-green-600 text-white font-black text-lg shadow-lg shadow-green-100"
            >
              記録する
            </Button>
          </div>
        </DialogContent>
      </Dialog>

      <BottomNav />
    </div>
  );
}

function HealthLogTab({ healthLogs, isTakaSensei, months }: {
  healthLogs: any[];
  isTakaSensei: boolean;
  months: number;
}) {
  const diaperLogs = healthLogs.filter((l: any) => l.type === "diaper");
  const poopLogs = diaperLogs.filter((l: any) => l.subType === "poop" || l.subType === "both");
  const tempLogs = healthLogs.filter((l: any) => l.type === "temp");
  const symptomLogs = healthLogs.filter((l: any) => l.type === "symptom");

  const latestTemp = tempLogs.length > 0 ? tempLogs[0] : null;
  const hasPoopColorChange = poopLogs.length >= 2 && poopLogs[0].poopColor !== poopLogs[1].poopColor && poopLogs[0].poopColor && poopLogs[1].poopColor;

  const aiAdvice = useMemo(() => {
    if (!isTakaSensei && months <= 3) {
      if (hasPoopColorChange) {
        return "うんちの色が変わっていますね。少し様子を見ましょうね。気になる場合はお医者さんに相談しましょう。";
      }
      if (poopLogs.some((l: any) => l.poopColor === "white" || l.poopColor === "red" || l.poopColor === "black")) {
        return "うんちの色が気になりますね。白・赤・黒のうんちは一度お医者さんに診てもらいましょうね。";
      }
      if (latestTemp && latestTemp.bodyTemperature >= 37.5) {
        return "体温が少し高めですね。母乳やミルクをこまめにあげて、様子を見ましょうね。";
      }
      return "24時間の記録をまとめています。毎日の記録が赤ちゃんの健康管理に役立ちますよ。";
    }
    if (latestTemp && latestTemp.bodyTemperature >= 38.0) {
      return "熱が高いっす！水分補給をしっかり、元気がなかったらお医者さんに相談っす！";
    }
    if (diaperLogs.length >= 6) {
      return "おむつ交換頑張ってるっす！これだけの回数は赤ちゃんの健康バロメーターっす！";
    }
    return "健康ログ、バッチリっす！毎日チェックで赤ちゃんの変化を見逃さないっす！";
  }, [isTakaSensei, months, hasPoopColorChange, poopLogs, latestTemp, diaperLogs.length]);

  return (
    <div className="space-y-4">
      <Card className="p-4 bg-teal-50/50 border-teal-100 rounded-3xl">
        <div className="flex items-start gap-3">
          <div className="bg-teal-100 p-2 rounded-2xl shrink-0">
            <Stethoscope className="w-5 h-5 text-teal-600" />
          </div>
          <div>
            <p className="font-bold text-sm text-teal-900">
              {isTakaSensei ? "タカ先生のアドバイス" : "みおさんのアドバイス"}
            </p>
            <p className="text-xs text-teal-700 mt-1 leading-relaxed" data-testid="text-health-advice">
              {aiAdvice}
            </p>
          </div>
        </div>
      </Card>

      <div className="grid grid-cols-3 gap-2">
        <Card className="p-3 rounded-2xl text-center" data-testid="stat-diaper-count">
          <Baby className="w-5 h-5 text-amber-500 mx-auto mb-1" />
          <p className="text-lg font-black text-gray-800">{diaperLogs.length}</p>
          <p className="text-[10px] font-bold text-gray-400">おむつ(24h)</p>
        </Card>
        <Card className="p-3 rounded-2xl text-center" data-testid="stat-temp-latest">
          <Thermometer className="w-5 h-5 text-red-500 mx-auto mb-1" />
          <p className="text-lg font-black text-gray-800">
            {latestTemp ? `${latestTemp.bodyTemperature}°` : "--"}
          </p>
          <p className="text-[10px] font-bold text-gray-400">最新体温</p>
        </Card>
        <Card className="p-3 rounded-2xl text-center" data-testid="stat-symptom-count">
          <Stethoscope className="w-5 h-5 text-teal-500 mx-auto mb-1" />
          <p className="text-lg font-black text-gray-800">{symptomLogs.length}</p>
          <p className="text-[10px] font-bold text-gray-400">症状メモ</p>
        </Card>
      </div>

      <Card className="rounded-3xl overflow-hidden" data-testid="health-log-list">
        <div className="p-4 border-b border-gray-100">
          <p className="font-bold text-sm text-gray-700">直近24時間の記録</p>
        </div>
        {healthLogs.length === 0 ? (
          <div className="p-6 text-center">
            <Activity className="w-8 h-8 text-gray-300 mx-auto mb-2" />
            <p className="text-xs text-gray-400 font-bold">まだ記録がありません</p>
          </div>
        ) : (
          <div className="divide-y divide-gray-50">
            {healthLogs.slice(0, 20).map((log: any) => (
              <HealthLogItem key={log.id} log={log} />
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

function HealthLogItem({ log }: { log: any }) {
  const time = format(new Date(log.createdAt), "HH:mm", { locale: ja });

  if (log.type === "diaper") {
    const typeLabel = log.subType === "pee" ? "おしっこ" : log.subType === "poop" ? "うんち" : log.subType === "both" ? "両方" : "おむつ";
    const colorLabel = log.poopColor ? POOP_COLOR_LABELS[log.poopColor] || "" : "";
    const consistLabel = log.poopConsistency ? POOP_CONSIST_LABELS[log.poopConsistency] || "" : "";
    const detail = (log.subType === "poop" || log.subType === "both") && (colorLabel || consistLabel)
      ? ` (${[colorLabel, consistLabel].filter(Boolean).join("・")})`
      : "";

    return (
      <div className="flex items-center gap-3 px-4 py-3" data-testid={`health-log-${log.id}`}>
        <div className="bg-amber-50 p-2 rounded-xl shrink-0">
          <Baby className="w-4 h-4 text-amber-500" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-gray-700">{typeLabel}{detail}</p>
          <p className="text-[10px] text-gray-400">{time}</p>
        </div>
      </div>
    );
  }

  if (log.type === "temp") {
    const isHigh = log.bodyTemperature >= 37.5;
    return (
      <div className="flex items-center gap-3 px-4 py-3" data-testid={`health-log-${log.id}`}>
        <div className={`p-2 rounded-xl shrink-0 ${isHigh ? "bg-red-50" : "bg-blue-50"}`}>
          <Thermometer className={`w-4 h-4 ${isHigh ? "text-red-500" : "text-blue-500"}`} />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-gray-700">
            体温 {log.bodyTemperature}°C
            {isHigh && <span className="text-red-500 text-xs ml-1">(高め)</span>}
          </p>
          <p className="text-[10px] text-gray-400">{time}</p>
        </div>
      </div>
    );
  }

  if (log.type === "symptom") {
    const symptomNames = log.symptoms
      ? log.symptoms.split(",").map((s: string) => SYMPTOM_LABELS[s] || s).join("、")
      : "";
    return (
      <div className="flex items-center gap-3 px-4 py-3" data-testid={`health-log-${log.id}`}>
        <div className="bg-teal-50 p-2 rounded-xl shrink-0">
          <Stethoscope className="w-4 h-4 text-teal-500" />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-bold text-gray-700">{symptomNames}</p>
          {log.symptomNote && (
            <p className="text-[10px] text-gray-500 mt-0.5">{log.symptomNote}</p>
          )}
          <p className="text-[10px] text-gray-400">{time}</p>
        </div>
      </div>
    );
  }

  return null;
}

function GrowthTab({ growthChartData, latestGrowth, weightGain, isTakaSensei, onAddGrowth }: {
  growthChartData: any[];
  latestGrowth: any;
  weightGain: number | null;
  isTakaSensei: boolean;
  onAddGrowth: () => void;
}) {
  const aiMsg = useMemo(() => {
    if (isTakaSensei) {
      if (weightGain && weightGain > 0) {
        return `前回から${weightGain}g増量っす！ナイスビルドアップ！この調子でいくっすよ！`;
      }
      if (latestGrowth) {
        return "成長記録バッチリっす！毎月の計測でしっかりモニタリングっす！";
      }
      return "身体測定をまだ記録してないっす！月に1回は計測して記録するのがオススメっすよ！";
    }
    if (weightGain && weightGain > 0) {
      return `前回から${weightGain}g増えましたね。順調に大きくなっていますよ。安心してくださいね。`;
    }
    if (latestGrowth) {
      return "成長記録をしっかりつけていますね。月に1回の計測が大切ですよ。";
    }
    return "身体測定はまだ記録されていませんね。月に1回程度の記録をおすすめしますよ。";
  }, [isTakaSensei, weightGain, latestGrowth]);

  return (
    <div className="space-y-4">
      <Card className="p-4 bg-green-50/50 border-green-100 rounded-3xl">
        <div className="flex items-start gap-3">
          <div className="bg-green-100 p-2 rounded-2xl shrink-0">
            <TrendingUp className="w-5 h-5 text-green-600" />
          </div>
          <div>
            <p className="font-bold text-sm text-green-900">
              {isTakaSensei ? "タカ先生のコメント" : "みおさんのコメント"}
            </p>
            <p className="text-xs text-green-700 mt-1 leading-relaxed" data-testid="text-growth-advice">
              {aiMsg}
            </p>
          </div>
        </div>
      </Card>

      {latestGrowth && (
        <div className="grid grid-cols-3 gap-2">
          <Card className="p-3 rounded-2xl text-center" data-testid="stat-weight">
            <Weight className="w-5 h-5 text-green-500 mx-auto mb-1" />
            <p className="text-lg font-black text-gray-800">
              {latestGrowth.weightGrams ? (latestGrowth.weightGrams / 1000).toFixed(1) : "--"}
            </p>
            <p className="text-[10px] font-bold text-gray-400">体重(kg)</p>
          </Card>
          <Card className="p-3 rounded-2xl text-center" data-testid="stat-height">
            <Ruler className="w-5 h-5 text-blue-500 mx-auto mb-1" />
            <p className="text-lg font-black text-gray-800">
              {latestGrowth.heightCm ? latestGrowth.heightCm.toFixed(1) : "--"}
            </p>
            <p className="text-[10px] font-bold text-gray-400">身長(cm)</p>
          </Card>
          <Card className="p-3 rounded-2xl text-center" data-testid="stat-head">
            <CircleDot className="w-5 h-5 text-purple-500 mx-auto mb-1" />
            <p className="text-lg font-black text-gray-800">
              {latestGrowth.headCircumferenceCm ? latestGrowth.headCircumferenceCm.toFixed(1) : "--"}
            </p>
            <p className="text-[10px] font-bold text-gray-400">頭囲(cm)</p>
          </Card>
        </div>
      )}

      {growthChartData.length >= 2 ? (
        <Card className="p-4 rounded-3xl" data-testid="chart-growth-curve">
          <p className="font-bold text-sm text-gray-700 mb-3">成長曲線</p>
          <div className="h-56">
            <ResponsiveContainer width="100%" height="100%">
              <LineChart data={growthChartData}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f0f0f0" />
                <XAxis dataKey="date" tick={{ fontSize: 11, fill: "#999" }} axisLine={false} tickLine={false} />
                <YAxis yAxisId="weight" tick={{ fontSize: 11, fill: "#999" }} axisLine={false} tickLine={false} label={{ value: "kg", position: "insideTopLeft", fontSize: 10, fill: "#999" }} />
                <YAxis yAxisId="cm" orientation="right" tick={{ fontSize: 11, fill: "#999" }} axisLine={false} tickLine={false} label={{ value: "cm", position: "insideTopRight", fontSize: 10, fill: "#999" }} />
                <Tooltip
                  contentStyle={{ borderRadius: 12, border: "1px solid #e5e7eb", fontSize: 12 }}
                  formatter={(value: number, name: string) => {
                    if (name === "weight") return [`${value.toFixed(1)} kg`, "体重"];
                    if (name === "height") return [`${value.toFixed(1)} cm`, "身長"];
                    return [`${value.toFixed(1)} cm`, "頭囲"];
                  }}
                />
                <Line yAxisId="weight" type="monotone" dataKey="weight" stroke="#22c55e" strokeWidth={2} dot={{ r: 4 }} name="weight" connectNulls />
                <Line yAxisId="cm" type="monotone" dataKey="height" stroke="#3b82f6" strokeWidth={2} dot={{ r: 4 }} name="height" connectNulls />
                <Line yAxisId="cm" type="monotone" dataKey="head" stroke="#a855f7" strokeWidth={2} dot={{ r: 4 }} name="head" connectNulls />
              </LineChart>
            </ResponsiveContainer>
          </div>
          <div className="flex items-center justify-center gap-4 mt-2 flex-wrap">
            <div className="flex items-center gap-1.5">
              <div className="w-3 h-3 rounded-sm bg-green-500" />
              <span className="text-[10px] text-gray-500 font-bold">体重</span>
            </div>
            <div className="flex items-center gap-1.5">
              <div className="w-3 h-3 rounded-sm bg-blue-500" />
              <span className="text-[10px] text-gray-500 font-bold">身長</span>
            </div>
            <div className="flex items-center gap-1.5">
              <div className="w-3 h-3 rounded-sm bg-purple-500" />
              <span className="text-[10px] text-gray-500 font-bold">頭囲</span>
            </div>
          </div>
        </Card>
      ) : (
        <Card className="p-6 rounded-3xl text-center" data-testid="chart-growth-empty">
          <TrendingUp className="w-10 h-10 text-gray-300 mx-auto mb-3" />
          <p className="font-bold text-sm text-gray-600">
            {growthChartData.length === 1 ? "もう1回記録するとグラフが表示されます" : "まだ測定データがありません"}
          </p>
          <p className="text-xs text-gray-400 mt-1">身体測定を記録すると成長曲線が表示されます</p>
        </Card>
      )}

      <Button
        data-testid="button-add-growth"
        onClick={onAddGrowth}
        className="w-full h-14 rounded-2xl bg-green-500 hover:bg-green-600 text-white font-black text-lg shadow-lg shadow-green-100"
      >
        <Plus className="w-5 h-5 mr-2" />
        身体測定を記録
      </Button>
    </div>
  );
}

